window.RECIPES = [{"slug":"abbys-famous-pecan-pie","title":"Abby's Famous Pecan Pie","from":null,"card":"0133","tags":["pie","dessert","pecan","pecans","nuts","corn syrup","brown sugar","eggs","thanksgiving","baking"],"ingredients":[{"heading":null,"items":["1 (9-inch) unbaked pie crust","1 cup light corn syrup","1 cup firmly packed dark brown sugar","3 eggs, slightly beaten","1/3 cup butter, melted","1/3 teaspoon salt","1 teaspoon vanilla","1 heaping cup pecan halves"]}],"directions":[{"heading":null,"items":["Heat oven to 350°. Prepare pie crust.","In large bowl, combine corn syrup, sugar, eggs, butter, salt and vanilla; mix well.","Pour filling into prepared pie crust; sprinkle with pecan halves.","Bake at 350° for 45 to 50 minutes or until center is set. (Toothpick inserted will come out clean when pie is done.) Cool.","If crust or pie appears to be getting too brown, cover with foil for remaining baking time."]}],"notes":["From a newspaper clipping. Serves 8 to 10.","Amounts for a triple batch are written in the margin: 3 cups corn syrup, 3 cups brown sugar, 9 eggs, 1 cup butter, 1 tsp. salt, 3 tsp. vanilla, 3 cups pecans.","Tip from the clipping: the bake time is for a gas oven; in an electric oven it may take 15 to 20 minutes longer. Start testing with a toothpick after 45 minutes.","Top with a bit of whipped cream or ice cream, but even plain, nothing tops this!"],"images":[{"file":"0133-b.jpg","label":"Clipping"},{"file":"0133-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"almendrado-salad","title":"Almendrado Salad","from":null,"card":"0051","tags":["salad","dessert","gelatin","egg whites","almonds","meringue","molded","custard sauce","mexican"],"ingredients":[{"heading":null,"items":["1 Tbsp. gelatin","1/4 cup cold water","1/4 cup boiling water","1/4 tsp. cream of tartar","1/4 tsp. salt","6 egg whites","2 tsp. vanilla","1 cup sugar","Chopped almonds","Pink and green coloring","Custard sauce"]}],"directions":[{"heading":null,"items":["Soften 1 Tbsp. gelatin in 1/4 cup cold water. Dissolve in 1/4 cup boiling water. Cool.","Add 1/4 tsp. cream of tartar and 1/4 tsp. salt to 6 egg whites; beat stiff.","Mix in 2 tsp. vanilla and 1 cup sugar (2 Tbsp. at a time). Beat in gelatin.","Divide in 3 parts. Add chopped almonds to one, tint one pink and one green.","Pour layers into loaf pan lined with wax paper. Chill; slice.","Serve with custard sauce."]}],"notes":[],"images":[{"file":"0051-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"apple-cider-vinegar-juice-drink","title":"Apple Cider Vinegar Juice Drink","from":null,"card":"loose-03","tags":["drink","beverage","apple cider vinegar","vinegar","grape juice","apple juice","juice","health tonic"],"ingredients":[{"heading":null,"items":["1 cup apple cider vinegar","3 cups grape juice","4 cups apple juice"]}],"directions":[{"heading":null,"items":["Mix (implied; the note just lists the ingredients).","Drink 1/4 cup per day [on?] empty stomach."]}],"notes":[],"images":[{"file":"loose-03.jpg","label":"Scan"}],"sameCard":[]},{"slug":"apple-crisp","title":"Apple Crisp","from":null,"card":"0035","tags":["dessert","crisp","apple crisp","apples","oats","brown sugar","cinnamon","lemon juice","butter","baking"],"ingredients":[{"heading":null,"items":["4 cups sliced cooking apples","1 Tbsp. lemon juice","1/3 cup flour","1 cup oats","1/2 cup brown sugar","1 tsp. cinnamon","1/3 cup melted butter"]}],"directions":[{"heading":null,"items":["Place apples in greased shallow baking dish. Sprinkle with lemon juice.","Combine dry ingredients. Add melted butter, mixing until crumbly.","Sprinkle crumb mixture over apples.","Bake in 375° F. 30 minutes or until apples are tender."]}],"notes":["6 servings."],"images":[{"file":"0035-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"apple-pie","title":"Apple Pie","from":null,"card":"0062","tags":["pie","dessert","apple","cinnamon","brown sugar","crumb topping","pastry","baking"],"ingredients":[{"heading":null,"items":["1/4 cup sugar","1 Tbsp. flour","1/2 tsp. cinnamon","Dash of salt","1 (No. 2) can sliced pie apples or 6 med. size tart fresh","1/4 cup butter","3/4 cup brown sugar","1/2 cup unsifted flour"]}],"directions":[{"heading":null,"items":["Blend together first 4 ingredients. Toss lightly with apples.","Spoon into pastry-lined 9\" Bake-A-Pie.","Combine butter, brown sugar and 1/2 cup flour. Sprinkle over pie filling.","Cover with top crust. Bake in 425° oven 35–40 minutes or until brown."]}],"notes":["Tip on the card: For best results bake pies in center of oven. Do not use Bake-A-Pie plates for baking pie shells. (Bake-A-Pie was a brand of pie plate.)"],"images":[{"file":"0062-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"apples-on-sticks","title":"Apples on Sticks","from":null,"card":"0002","tags":["candy","dessert","apple","halloween","cinnamon","corn syrup","sugar"],"ingredients":[{"heading":null,"items":["Small to medium apples (about 6)","Skewers","A few drops of cinnamon flavoring","Bright red food coloring","1 recipe Glacé Syrup (below)"]},{"heading":"Glacé Syrup","items":["2 cups sugar","2/3 cup light corn syrup","1 cup water","A few grains of salt"]}],"directions":[{"heading":null,"items":["Wash and dry apples; insert a skewer in the stem end of each.","Prepare glacé syrup. When syrup is removed from heat, flavor with a few drops of cinnamon and color bright red with food coloring. Stir as little as possible, but distribute flavoring and color evenly.","Holding an apple by the skewer, dip it quickly into the hot syrup, making certain the syrup covers it entirely. Remove and twist to spread the syrup evenly.","Place upright to dry in a rack which will keep the apples from touching. (A wire cake cooler is good.)"]},{"heading":"Glacé Syrup","items":["Combine ingredients in a small saucepan. Place over moderate heat and stir constantly until mixture begins to boil.","Cook without stirring to 300°F (brittle), using a low flame after 280°F in order to keep the syrup a light straw color.","As crystals collect on the sides of the pan, wipe them away with a damp cloth."]}],"notes":["A Halloween treat.","One recipe of glacé syrup covers six small to medium apples. Leftover syrup may be used for lollipops or candy squares."],"images":[{"file":"0002-b.jpg","label":"Front"},{"file":"0002-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"applesauce-cake","title":"Applesauce Cake","from":null,"card":"0036","tags":["cake","dessert","applesauce","apple","raisins","nuts","cinnamon","cloves","spice cake","frosting","brown sugar","baking"],"ingredients":[{"heading":null,"items":["1 cup shortening","2 cup sugar","2 eggs","1 cup applesauce","2 cup flour","1/4 tsp. salt","1 tsp. B. Powder","[1/2?] tsp. soda","1 tsp. cinnamon","1/2 cloves","1/2 raisin and nut"]},{"heading":"Frosting","items":["1 lb. butter","2 Tbsp. brown sugar","Cream","Powdered sugar"]}],"directions":[{"heading":null,"items":["Beat shortening, sugar, eggs, and applesauce well.","Mix flour, salt, baking powder, soda, cinnamon, and cloves together, and add.","Add raisins and nuts.","Bake 350° 45 minutes."]},{"heading":"Frosting","items":["No directions are given."]}],"notes":[],"images":[{"file":"0036-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"banana-bread","title":"Banana Bread","from":null,"card":"0024","tags":["bread","quick bread","banana","pecans","nuts","shortening","baking"],"ingredients":[{"heading":null,"items":["1/2 cup shortening","1/2 cup sugar","2 eggs, well beaten","1 1/2 cups crushed bananas","2 cups sifted flour","1/2 tsp. soda","1 tsp. baking powder","1/4 tsp. salt","1/4 cup pecans"]}],"directions":[{"heading":null,"items":["Cream together shortening, sugar and eggs.","Combine in order given. Mix, beat with a few quick strokes.","Put in greased and floured bread pan and bake 40 minutes at 350° F."]}],"notes":[],"images":[{"file":"0024-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"banana-nut-cake","title":"Banana Nut Cake","from":null,"card":"0072","tags":["cake","dessert","banana","pecans","nuts","buttermilk","shortening","vanilla","baking"],"ingredients":[{"heading":null,"items":["1 1/2 cups sugar","1/2 cup shortening","2 eggs","2 large mashed bananas","1 cup broken pecans","2 cups sifted flour","1 tsp. soda (barely heaping)","1/4 tsp. salt","1 cup buttermilk","1 tsp. vanilla"]}],"directions":[{"heading":null,"items":["Cream sugar, shortening and then eggs.","Add dry mixture alternately with buttermilk and vanilla.","Add bananas with mixer. Add pecans.","Bake at 350° for 35 to 40 minutes in two 9\" pans or at 325° for about 1 hour in angel food cake pan."]}],"notes":[],"images":[{"file":"0072-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"barbecue-chicken","title":"Barbecue Chicken","from":null,"card":"0058","tags":["main dish","chicken","barbecue","barbecue sauce","onion","catsup","worcestershire","chili powder","baked"],"ingredients":[{"heading":null,"items":["1/2 cup margarine (1 stick, 1/4 lb.)","1/2 cup sliced onion","1 tsp. salt","1/4 tsp. pepper","1/4 cup water","1 Tbsp. vinegar","1 Tbsp. sugar","1 Tbsp. Wor. sauce","1/2 tsp. chili powder","1/2 cup catsup","Chicken"]}],"directions":[{"heading":null,"items":["Pour over clean chicken. Bake 350° for about an hour."]}],"notes":["\"Wor. sauce\" is Worcestershire sauce."],"images":[{"file":"0058-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"barbecue-sauce","title":"Barbecue Sauce","from":null,"card":"0096","tags":["sauce","barbecue","tomato sauce","butter","hot pepper","red pepper","onion"],"ingredients":[{"heading":null,"items":["1 can water","1 stick salted butter","1 can tomato sauce","2 tbs. barbecue sauce","2 tbs. hot pepper, red","1 onion"]}],"directions":[{"heading":null,"items":["(No directions on the card.)"]}],"notes":[],"images":[{"file":"0096-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"barbecued-round-steak","title":"Barbecued Round Steak","from":null,"card":"0016","tags":["main dish","beef","steak","round steak","barbecue","tomato soup","onion","celery","worcestershire sauce","mustard"],"ingredients":[{"heading":null,"items":["2 pounds round steak","1/4 cup seasoned flour","3 Tbsp. shortening","1/3 cup minced onion","1/3 cup minced celery","1 small clove garlic","1 can (10 1/2 oz.) tomato soup","2 Tbsp. brown sugar","2 Tbsp. Worcestershire sauce","2 Tbsp. lemon juice","2 tsp. prepared mustard","1/4 tsp. Tabasco sauce"]}],"directions":[{"heading":null,"items":["Pound flour into steak; cut into 3\" squares.","Melt shortening in skillet on gas burner with a brain set at 250°; brown steak with onion, celery and garlic.","Combine remaining ingredients; pour over steak.","Cover and cook on gas burner with a brain set at 225° or in a gas oven at 350° for about 1 1/2 hours or until tender."]}],"notes":["Serves 6.","A \"gas burner with a brain\" is a thermostat-controlled gas stove burner, an old gas-company phrase."],"images":[{"file":"0016-a.jpg","label":"Front"},{"file":"0016-b.jpg","label":"Back"}],"sameCard":[]},{"slug":"beef-pie","title":"Beef Pie","from":null,"card":"0032","tags":["pie","beef pie","main dish","casserole","beef","leftovers","mushroom soup","potatoes","green beans","onion","biscuits"],"ingredients":[{"heading":null,"items":["1 med. onion","2 lb. butter","1 can mushroom soup","1 tsp. steak sauce","1 cup diced potatoes","1/2 cup beans","1 cup meat (beef), cut up","1/2 cup milk","Biscuits"]}],"directions":[{"heading":null,"items":["Cook butter and onions in skillet.","Cut up 1 cup meat; mix beans, 1/2 cup milk, soup.","Add diced potatoes, 1/2 cup green beans, 1 cup beef. Simmer 5 minutes.","Place biscuits on top. Bake."]}],"notes":[],"images":[{"file":"0032-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"beef-taco-skillet","title":"Beef Taco Skillet","from":null,"card":"loose-04","tags":["main dish","skillet","mexican","ground beef","beef","tomato soup","campbell's","salsa","tortillas","cheddar","cheese","quick"],"ingredients":[{"heading":null,"items":["1 lb. ground beef","1 can (10 3/4 oz.) Campbell's Tomato Soup (Regular or 25% Less Sodium)","1/2 cup salsa","1/2 cup water","6 flour tortillas (6\"), cut into 1\" pieces","1/2 cup shredded Cheddar cheese"]}],"directions":[{"heading":null,"items":["Cook beef in 10\" skillet until well browned, stirring to break up meat. Pour off fat.","Stir in soup, salsa, water, tortillas. Heat to a boil. Reduce heat to low and cook for 5 min. Stir. Top with cheese."]}],"notes":["From a Campbell's magazine ad (2007). Makes 4 servings. Prep: 5 min. Cook: 20 min.","Variations from the ad: Creamy Mexican Fiesta: stir in 1/2 cup sour cream with soup. Ranchero Style: use corn tortillas instead of flour tortillas and shredded Mexican cheese blend instead of Cheddar."],"images":[{"file":"loose-04.jpg","label":"Scan"}],"sameCard":[]},{"slug":"boston-baked-beans","title":"Boston Baked Beans","from":null,"card":"0127","tags":["beans","side dish","pinto beans","pork and beans","brown sugar","ketchup","mustard"],"ingredients":[{"heading":null,"items":["Pinto beans","Brown sugar","Ketchup","Mustard","1 can pork & beans"]}],"directions":[{"heading":null,"items":["Start with pinto beans; add brown sugar, ketchup, mustard and a can of pork & beans."]}],"notes":["Written on the back of a Hallmark photo-album page."],"images":[{"file":"0127-b.jpg","label":"Front"},{"file":"0127-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"bread-and-butter-pickles","title":"Bread and Butter Pickles","from":null,"card":"0054","tags":["pickles","canning","cucumbers","onions","green peppers","vinegar","mustard seed","celery seed","turmeric","cloves"],"ingredients":[{"heading":null,"items":["1 gal. cucumbers","8 small onions, white","2 green peppers, shredded","1/2 cup salt","Ice"]},{"heading":"Syrup","items":["5 cups sugar","1/2 tsp. gr. cloves","1 tsp. celery seed","1 1/2 tsp. turmeric","2 Tbsp. mustard seed","5 cups vinegar"]}],"directions":[{"heading":null,"items":["Select crisp cucumbers. Wash (but do not pare). Slice criss cross in paper thin slices. Slice onions and peppers.","Mix salt with vegetables and bury pieces of ice among veg. Cover with a weight and let stand 3 hours."]},{"heading":"Syrup","items":["Mix sugar and spices and vinegar and pour over cucumbers.","Place over low heat, stir occasionally. Heat to scalding but do not boil.","Seal in jars."]}],"notes":[],"images":[{"file":"0054-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"browned-beef-stew","title":"Browned Beef Stew","from":null,"card":"0086","tags":["stew","main dish","beef","dr pepper","carrots","potatoes","onions","celery","peas"],"ingredients":[{"heading":null,"items":["3 pounds boneless stew meat (beef)","1/4 cup flour","3 teaspoons salt","1 teaspoon black pepper","3 tablespoons shortening or beef suet","2 cups beef stock or bouillon","2 cups Dr Pepper","2 cups carrots, chunks","1 1/2 cups onions, chunks","3 cups potatoes, chunks","1 cup (1/2-inch) celery crescents","1 cup frozen or fresh garden peas"]}],"directions":[{"heading":null,"items":["Sprinkle meat with the salt and pepper and dust with the 1/4 cup flour.","In a large stew kettle, brown meat in the 3 tablespoons fat until very brown.","Add beef stock or bouillon and Dr Pepper and cook at a low temperature until meat is tender.","Add chunked vegetables: carrots, potatoes, onions and celery. Cook until vegetables are beginning to be tender.","Add frozen peas and cook at least 10 minutes longer."]}],"notes":["From a Dr Pepper recipe card (1966).","Yield: 8 servings.","If stew must be reheated, heat in a slow oven until hot."],"images":[{"file":"0086-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"butterscotch-cream-pie","title":"Butterscotch Cream Pie","from":null,"card":"0021","tags":["pie","cream pie","dessert","butterscotch","brown sugar","milk","egg yolks","butter","vanilla"],"ingredients":[{"heading":null,"items":["1/2 tsp. salt","1 cup water","1 2/3 cup milk","1 cup (packed) brown sugar","1/2 cup cake flour","1/3 cup butter","3 egg yolks, slightly beaten","1 1/2 tsp. vanilla"]}],"directions":[{"heading":null,"items":["Mix sugar, flour and salt in sauce pan. Gradually stir in water and milk. Add butter.","Cook over med. heat, stirring constantly, until mixture thickens and boils. Boil 1 minute. Remove from heat.","Gradually stir 1/2 of hot mixture into egg yolks. Blend into hot mixture in sauce pan.","Boil 1 minute more, stirring constantly.","Add vanilla and pour into pie shell."]}],"notes":[],"images":[{"file":"0021-a.jpg","label":"Front"},{"file":"0021-b.jpg","label":"Back"}],"sameCard":[]},{"slug":"butterscotch-sauce","title":"Butterscotch Sauce","from":null,"card":"0027","tags":["sauce","dessert topping","butterscotch","corn syrup","brown sugar","butter","ice cream","cake"],"ingredients":[{"heading":null,"items":["1 cup light corn syrup","1 cup light brown sugar","1/4 tsp. salt","1/2 cup milk","3 Tbsp. butter","1 tsp. vanilla"]}],"directions":[{"heading":null,"items":["Combine ingredients in saucepan.","Cook over medium heat to a full rolling boil and continue cooking for 5 minutes, stirring occasionally.","Cool and spoon on servings of cake or ice cream-topped cake."]}],"notes":[],"images":[{"file":"0027-b.jpg","label":"Front"},{"file":"0027-a.jpg","label":"Back"}],"sameCard":["creamy-honey-frosting","magic-topping"]},{"slug":"butterscotch-slices","title":"Butterscotch Slices","from":null,"card":"0069","tags":["cookies","icebox cookies","dessert","butterscotch","brown sugar","butter","nuts","lemon","vanilla","baking"],"ingredients":[{"heading":null,"items":["3 1/2 cups flour","2 1/2 tsp. Baking Powder","1/2 tsp. Salt","1 1/2 tsp. Lemon Extract","1 cup Chopped Nuts","1 cup butter","1 1/2 c. Brown Sugar","2 Eggs","1 1/2 tsp. Vanilla"]}],"directions":[{"heading":null,"items":["Add baking powder, salt and flour - sift.","Cream butter, sugar. Add eggs, one at a time, beating thoroughly after each addition.","Shape in roll and roll in wax paper. Chill until firm.","Bake 425°. 5 - 6 minutes."]}],"notes":[],"images":[{"file":"0069-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"buttery-crunch-cookies","title":"Buttery Crunch Cookies","from":null,"card":"0041","tags":["cookies","dessert","butter","almond extract","oats","cereal","grape-nuts","baking"],"ingredients":[{"heading":null,"items":["3/4 cup butter","1 tsp. almond extract","3/4 cup sugar","1 egg","1 1/2 cups flour","1/2 tsp. baking powder","1/2 cup malted cereal nuts","1/2 cup uncooked rolled oats","Sugar, for dipping the glass"]}],"directions":[{"heading":null,"items":["Cream the butter and almond extract together. Add the sugar gradually, creaming until fluffy. Add the egg and beat thoroughly.","Blend the flour and baking powder; add in thirds to the creamed mixture, mixing until blended after each addition. Stir in cereals.","Refrigerate the dough until easy to handle.","Shape into 1-inch balls. Place about 2 inches apart on ungreased cookie sheets. Dip the bottom of a glass in sugar and press each ball to flatten slightly, then form crisscross design with a fork.","Bake at 375° F. 8 to 10 minutes or until lightly browned around edges."]}],"notes":["Makes about 5 1/2 dozen cookies.","\"Malted cereal nuts\" is a Grape-Nuts-type cereal."],"images":[{"file":"0041-b.jpg","label":"Front"},{"file":"0041-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"cake-mix-cookies","title":"Cake Mix Cookies","from":null,"card":"0083","tags":["cookies","dessert","cake mix","eggs","vegetable oil","powdered sugar","easy","baking"],"ingredients":[{"heading":null,"items":["2 egg","1 box cake mix","1/2 cup vegetable oil","Powdered sugar, for dusting"]}],"directions":[{"heading":null,"items":["Mix together cake mix, egg & oil in a med. bowl.","Make little balls with the dough and set on ungreased cookie sheets. Cover pan with parchment paper.","Bake at 375° for 8-10 mins.","Allow to cool, then dust lightly with powdered sugar."]}],"notes":["\"Jace\" is written at the top of the card."],"images":[{"file":"0083-b.jpg","label":"Front"},{"file":"0083-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"canned-fruit-pie","title":"Canned Fruit Pie","from":null,"card":"0011","tags":["pie","dessert","fruit","canned fruit","fruit juice","pie filling","baking"],"ingredients":[{"heading":null,"items":["2/3 to 1 cup sugar","4 tbs flour","[1/2?] cup fruit juice"]}],"directions":[{"heading":null,"items":["Cook sugar, flour and fruit juice until thick.","Pour over fruit. Bake 425°."]}],"notes":[],"images":[{"file":"0011-b.jpg","label":"Front"},{"file":"0011-a.jpg","label":"Back"}],"sameCard":["fresh-fruit-pie","lemon-parfait-pie-and-fruit"]},{"slug":"caramel-topping","title":"Caramel Topping","from":null,"card":"0079","tags":["sauce","dessert topping","caramel","butter","brown sugar","cinnamon","vanilla","bananas","rum","pecans","ice cream"],"ingredients":[{"heading":null,"items":["Butter","Brown sugar","Cinnamon","Vanilla","Bananas","Rum","Pecans"]}],"directions":[{"heading":null,"items":["Heat in skillet. Serve over ice cream, etc."]}],"notes":["\"Wheatfield Cook\" is written at the top of the card."],"images":[{"file":"0079-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"carnation-five-minute-fudge","title":"Carnation Five-Minute Fudge","from":null,"card":"0052","tags":["candy","fudge","dessert","chocolate","chocolate chips","marshmallows","evaporated milk","carnation","peppermint","coconut","nuts","walnuts","pecans","peanuts"],"ingredients":[{"heading":null,"items":["2/3 cup (small can) undiluted Carnation Evap. Milk","1 2/3 cups sugar","1/2 tsp. salt","1 1/2 cups (about 16 medium) diced marshmallows","1 1/2 cups (1 1/2 6-ounce packages) semi-sweet choc. pieces","1 tsp. vanilla","Nuts, if desired"]},{"heading":"Peppermint Fudge","items":["1/4 cup coarsely broken peppermint stick candy"]},{"heading":"Upside Down Coconut Fudge","items":["1 cup flaked coconut"]},{"heading":"Nut Fudge","items":["1/2 cup chopped walnuts, pecans or peanuts"]}],"directions":[{"heading":null,"items":["Combine Carnation, sugar and salt in saucepan over medium heat. Bring to boil, and cook 4 to 5 minutes, stirring constantly. (Start timing when mixture starts to \"bubble\" around edges of pan.)","Remove from heat. Add marshmallows, chocolate and vanilla. Stir vigorously for 1 min. (or until marshmallows are completely melted and blended).","Pour into 8-inch square buttered pan. Garnish with nuts, if desired. Cool. Cut in squares."]},{"heading":"Peppermint Fudge","items":["Sprinkle 1/4 cup coarsely broken peppermint stick candy over top of fudge in pan."]},{"heading":"Upside Down Coconut Fudge","items":["Spread 1 cup flaked coconut on bottom of buttered 8-inch square pan. Top with fudge."]},{"heading":"Nut Fudge","items":["Add 1/2 cup chopped walnuts, pecans or peanuts to fudge mixture before pouring in pan."]}],"notes":["From a Carnation evaporated milk recipe."],"images":[{"file":"0052-b.jpg","label":"Front"},{"file":"0052-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"cashew-caramel-fudge","title":"Cashew Caramel Fudge","from":null,"card":"0145","tags":["candy","fudge","dessert","cashews","nuts","caramel","chocolate","chocolate chips","marshmallow creme","evaporated milk"],"ingredients":[{"heading":null,"items":["2 tsp. + 1/2 cups butter, softened & divided","1 can (5 oz.) evaporated [milk?]","2 1/2 cup sugar","2 cups (12 oz.) semisweet chips","1 jar marshmallow creme","24 caramels, quartered","3/4 cup salted cashew halves","1 tsp. vanilla extract"]}],"directions":[{"heading":null,"items":["Line 9 in. square baking pan [with?] foil; butter. Set aside.","[In?] a large heavy saucepan [combine?] milk, sugar & remaining [butter?].","[Cook?] & stir over medium heat until sugar is dissolved. Bring to a rapid boil; boil for 5 minutes, stirring constantly.","Remove from heat; stir in chocolate chips & marshmallow creme until melted. Fold in caramels, cashews & vanilla. Mix well.","Pour into prepared pan. Cool.","Remove from pan; cut into 1 in. squares. Store at room temperature."]}],"notes":["Written on the back of an insurance payment receipt from 2001.","The butter is divided: 2 tsp. for buttering the foil-lined pan, the rest goes into the saucepan."],"images":[{"file":"0145-b.jpg","label":"Front"},{"file":"0145-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"cheese-roll-on-crackers","title":"Cheese Roll on Crackers","from":null,"card":"0066","tags":["appetizer","snack","cheese","velveeta","cream cheese","nuts","garlic","worcestershire","no-bake"],"ingredients":[{"heading":null,"items":["1 lb. Velveeta cheese","1 1/2 pkg. cream cheese","1 cup fine chopped nuts","1/2 tsp. clove garlic or salt","1 tsp. Worcestershire sauce","1/2 tsp. red pepper"]}],"directions":[{"heading":null,"items":["Soften cheese; mix; roll in paper and chill."]}],"notes":[],"images":[{"file":"0066-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"cheesy-chicken-enchiladas","title":"Cheesy Chicken Enchiladas","from":null,"card":"0147","tags":["main dish","mexican","enchiladas","chicken","cheese","velveeta","cream cheese","tortillas","green chilies","tomato","microwave","kraft"],"ingredients":[{"heading":null,"items":["1/2 cup chopped onion","1 garlic clove, minced","1 tablespoon oil","2 cups chopped cooked chicken","1 can (4 ounces) chopped green chilies","1/4 cup chicken broth","2 teaspoons chili powder","1 teaspoon ground cumin","4 ounces Philadelphia Brand Cream Cheese, cubed","6 flour tortillas (6-inch)","1/4 pound Velveeta Process Cheese Spread, cubed","2 tablespoons milk","1/2 cup chopped tomato, divided"]}],"directions":[{"heading":null,"items":["Microwave onion, garlic and oil in 2-quart microwave-safe casserole on HIGH 2 to 3 minutes or until tender, stirring after 2 minutes.","Stir in chicken, chilies, broth and seasonings.","Microwave on HIGH 4 minutes or until thoroughly heated. Add cream cheese; stir until cream cheese is melted.","Spoon 1/3 cup chicken mixture onto each tortilla; roll up. Place, seam side down, in 8-inch square microwave-safe baking dish.","Microwave Velveeta Process Cheese Spread, milk and 1/4 cup tomato in medium microwave-safe bowl on HIGH 2 to 3 minutes or until Velveeta Process Cheese Spread is melted, stirring after each minute.","Pour sauce over tortillas; top with remaining tomatoes.","Microwave on HIGH 6 to 8 minutes or until thoroughly heated, turning dish after 3 minutes."]}],"notes":["From a Kraft Velveeta recipe leaflet, \"one of the many delicious Kraft recipes you'll find in the Official U.S. Olympic Training Table Cookbook.\"","Makes 6 servings. Prep time: 15 minutes. Microwave cooking time: 13 minutes.","Also on the same leaflet: Shells and Cheese Florentine, Mexican Chili Burgers, Chicken Fajita Pizzas, Tex-Mex Fondue."],"images":[{"file":"0147-b.jpg","label":"Front"},{"file":"0147-a.jpg","label":"Back"}],"sameCard":["shells-and-cheese-florentine","mexican-chili-burgers","chicken-fajita-pizzas","tex-mex-fondue"]},{"slug":"cherry-nut-cookies","title":"Cherry Nut Cookies","from":null,"card":"0006","tags":["cookies","dessert","cherry","nuts","brown sugar","baking"],"ingredients":[{"heading":null,"items":["1 cup brown sugar","1 egg","1/3 cup shortening (heaping)","2 cups flour","1/2 tsp. soda","2 Tbsp. milk","1 tsp. vanilla","1/2 cup cherries (quartered)","1/2 cup chopped nuts"]}],"directions":[{"heading":null,"items":["Mix together brown sugar, egg, shortening, milk and vanilla.","Sift together flour and soda, and add.","Mix well and add cherries and nuts.","Bake on a greased cookie sheet at 375° for 10–12 minutes."]}],"notes":["Amounts for a triple batch are written on the card: 3 cups brown sugar, 3 eggs, 1 cup shortening, 6 cups flour, 1 1/2 tsp. soda, 6 Tbsp. milk, 3 tsp. vanilla, 1 1/2 cups cherries, 1 1/2 cups nuts."],"images":[{"file":"0006-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chess-pie-meringue","title":"Chess Pie Meringue","from":null,"card":"0065","tags":["pie","dessert","chess pie","meringue","raisins","butter","eggs","lemon","orange","baking"],"ingredients":[{"heading":null,"items":["1/3 cup butter","1 cup sugar","1 1/2 cups chopped raisins","3 1/2 Tbsp. flour","3 egg yolks","2 cups water","1/2 tsp. lemon extract","3 egg whites","2 Tbsp. powdered sugar","1/4 tsp. orange extract"]}],"directions":[{"heading":null,"items":["Cook in double boiler until thick. Pour in baked shells.","325° for 12 minutes."]}],"notes":[],"images":[{"file":"0065-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chicken-and-dumplings","title":"Chicken & Dumplings","from":null,"card":"0081","tags":["main dish","chicken","dumplings","soup","pressure cooker","flour","shortening","milk"],"ingredients":[{"heading":null,"items":["1 small chicken"]},{"heading":"Dumplings","items":["1 cup flour","1 tsp salt","1/2 tsp baking powder","1 heaping tablespoon shortening","1/2 cup milk"]}],"directions":[{"heading":null,"items":["Cook chicken for 45 min @ 10# pressure."]},{"heading":"Dumplings","items":["Mix flour, salt, baking powder and shortening. Add milk. Knead into thick dough.","Roll out into squares (1\"-1 1/2\").","In a separate bowl, clean chicken from bones, skin etc.","Bring chicken broth to rolling boil. Drop squares into rolling boil one at a time.","Cook until squares are not [doughy?]."]}],"notes":["\"10#\" means 10 pounds of pressure in the pressure cooker."],"images":[{"file":"0081-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chicken-fajita-pizzas","title":"Chicken Fajita Pizzas","from":null,"card":"0147","tags":["main dish","pizza","mexican","chicken","cheese","velveeta","tortillas","salsa","green pepper","tomato","olives","kraft"],"ingredients":[{"heading":null,"items":["4 flour tortillas (6-inch)","1 1/2 cups (6 ounces) Velveeta Mexican Shredded Process Cheese Food","1 cup shredded cooked chicken","1/2 cup salsa","1/2 cup chopped green bell pepper","1/2 cup seeded chopped tomato","1/4 cup pitted ripe olive slices"]}],"directions":[{"heading":null,"items":["Heat oven to 350°.","Place tortillas on cookie sheet; sprinkle 2 tablespoons Velveeta Mexican Shredded Process Cheese Food on each tortilla.","Bake 4 to 5 minutes or until Velveeta Mexican Shredded Process Cheese Food melts.","Toss chicken with salsa; spread on tortillas.","Toss green bell peppers with remaining Velveeta Mexican Shredded Process Cheese Food; sprinkle over chicken mixture.","Bake 7 to 10 minutes or until thoroughly heated and Velveeta Mexican Shredded Process Cheese Food is melted.","Top with remaining ingredients."]}],"notes":["From a Kraft Velveeta recipe leaflet. Makes 4 servings. Prep time: 10 minutes. Cooking time: 15 minutes.","Also on the same leaflet: Cheesy Chicken Enchiladas, Shells and Cheese Florentine, Mexican Chili Burgers, Tex-Mex Fondue."],"images":[{"file":"0147-b.jpg","label":"Front"},{"file":"0147-a.jpg","label":"Back"}],"sameCard":["cheesy-chicken-enchiladas","shells-and-cheese-florentine","mexican-chili-burgers","tex-mex-fondue"]},{"slug":"chicken-pie","title":"Chicken Pie","from":null,"card":"0029","tags":["pie","chicken pie","main dish","casserole","chicken","pearl onions","peas","celery","carrot","pie crust","biscuits"],"ingredients":[{"heading":null,"items":["4–5 lb. stewing hen","Boiling water","2 parsley sprigs","3–4 stalks celery","1 carrot","1 sliced onion","1 Tbsp. salt","Dash of pepper","2 cups pearl onions","1/2 cup peas","1/2 cup flour for each 4 cups broth","1 cup milk","Salt and pepper to season","Pie crust or biscuit dough"]}],"directions":[{"heading":null,"items":["Cut up stewing hen, place in kettle. Cover with boiling water.","Add to kettle parsley sprigs, celery, carrot, sliced onion, 1 Tbsp. salt, and a dash of pepper.","Boil 2 minutes, lower heat and simmer gently 2–3 hours.","Cool, remove meat from bones and place in casserole. Add pearl onions and peas.","Thicken broth by straining broth from chicken and to each 4 cups broth add 1/2 cup flour, combined with 1 cup milk to form paste. Cook until thickened. Season with salt, pepper.","Cover casserole with pie crust or biscuit dough. Make large slits in crust.","Bake at 450° until crust browns and serve at once."]}],"notes":["Serves 6–8."],"images":[{"file":"0029-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chicken-quesadilla","title":"Chicken Quesadilla","from":null,"card":"0098","tags":["main dish","mexican","quesadilla","chicken","cheese","tortillas","onions","peppers"],"ingredients":[{"heading":null,"items":["Tortillas","Chicken, shredded","Cheese","Onions, sautéed","Peppers, to taste"]}],"directions":[{"heading":null,"items":["(No directions on the card.)"]}],"notes":["Also written on the card, as sides: \"Ramen noodles, mix with hot water\" and \"Rice\"."],"images":[{"file":"0098-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chicken-soup","title":"Chicken Soup","from":"Joe","card":"0128","tags":["soup","main dish","chicken","noodles","curry","onion","garlic","celery","carrots","potatoes"],"ingredients":[{"heading":null,"items":["Chicken breast, cut up","[4?] bouillon","Qt. water","Curry powder, [a?] [pinch?]","Onion","Garlic","Celery","Carrots","Potatoes","Noodles, 2 cups"]}],"directions":[{"heading":null,"items":["1 hr.","Simmer noodles, 15 min."]}],"notes":["Joe's recipe."],"images":[{"file":"0128-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chiffon-cake-0050","title":"Chiffon Cake","from":null,"card":"0050","tags":["cake","chiffon cake","dessert","eggs","egg whites","cream of tartar","oil","baking"],"ingredients":[{"heading":null,"items":["2 cups flour","1 1/2 cups sugar","3 tsp. baking powder","1 tsp. salt","1/2 cup cooking oil","7 unbeaten egg yolks","3/4 cup cold water","7 or 8 egg whites","1/2 tsp. cream of tartar","Flavor"]}],"directions":[{"heading":null,"items":["Make well and add oil, unbeaten egg yolks and cold water. Beat until smooth.","Whip 7 or 8 egg whites with 1/2 tsp. cream of tartar until very stiff. Add flavor.","Fold in flour.","Bake at 325° for 1 hr."]}],"notes":["Written on the back of the Cinnamon Apple Salad card.","Another version is on card 0043."],"images":[{"file":"0050-b.jpg","label":"Front"},{"file":"0050-a.jpg","label":"Back"}],"sameCard":["cinnamon-apple-salad"]},{"slug":"chiffon-cake","title":"Chiffon Cake","from":null,"card":"0043","tags":["cake","chiffon cake","dessert","eggs","egg whites","cooking oil","cream of tartar","flour","sugar","baking"],"ingredients":[{"heading":"I","items":["2 cups sifted flour (spoon lightly into cup)","1 1/2 cups sugar","3 tsp. baking powder","1 tsp. salt","1/2 cup cooking oil","7 unbeaten egg yolks","3/4 cup cold water"]},{"heading":"II","items":["Egg whites (7 or 8 – 1 cup)","1/2 tsp cream of tartar"]}],"directions":[{"heading":"I","items":["Sift together flour, sugar, baking powder and salt. Make a well and add oil, egg yolks and cold water.","Beat with spoon until smooth."]},{"heading":"II","items":["Beat egg whites and cream of tartar until very stiff.","Pour egg yolk mixture gradually over whites; fold in.","Bake 325° 55 minutes."]}],"notes":["Another version is on card 0050."],"images":[{"file":"0043-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chili-0108","title":"Chili","from":null,"card":"0108","tags":["chili","main dish","beef","ground beef","dr pepper","tomato paste","beans","chili powder","onion","garlic"],"ingredients":[{"heading":null,"items":["2 pounds beef (coarse grind)","1 clove garlic (minced)","1/2 cup onions (chopped)","1 tablespoon salt","1 6-oz. can tomato paste","2 cups Dr Pepper","1 cup water","1 tablespoon paprika","2 tablespoons chili powder","1 teaspoon black pepper","1/8 teaspoon oregano","1 pint cooked beans (optional)"]}],"directions":[{"heading":null,"items":["Place ground meat in large heavy saucepan with onions and garlic. Cook, stirring with fork to break up meat, until slightly browned.","Add salt, tomato paste, Dr Pepper, and water. Cover, simmer until meat is very tender and mixture is desired thickness.","Add chili powder, paprika, oregano, pepper and beans (if desired). Cook 5 to 10 minutes longer. Serve very hot."]}],"notes":["From a Dr Pepper recipe card (1966).","Yield: 6 one-cup servings.","Tip on the card: Garlic and other seasonings may be increased if stronger seasoning is desired."],"images":[{"file":"0108-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chili-0137","title":"Chili","from":"Debbie Strickland","card":"0137","tags":["chili","soup","main dish","hamburger","ground beef","kidney beans","beans","tomatoes","v-8","green pepper","onion","celery","honey"],"ingredients":[{"heading":null,"items":["2 lbs. hamburger","Green pepper","Onion","Celery","1 qt. V-8 (Spicy Hot)","1 qt. chopped tomatoes (large can)","3 tablespoons honey","1/4 - 1/2 tsp. chili powder","1 can (veg. can size) red light kidney beans","Salt and pepper to taste"]}],"directions":[{"heading":null,"items":["Brown hamburger, green pepper, onion and celery together.","In large kettle combine V-8, chopped tomatoes, honey, chili powder and kidney beans.","Add browned meat mixture to sauce. Salt and pepper to taste."]}],"notes":["From Debbie Strickland, on a \"My Favorite Recipe\" card."],"images":[{"file":"0137-b.jpg","label":"Front"},{"file":"0137-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"chili","title":"Chili","from":"Brother Goodman","card":"0094","tags":["chili","main dish","soup","hamburger","ground beef","beef","onion","tomatoes","chili beans","beans"],"ingredients":[{"heading":null,"items":["3/4 lb. hamburger","1/2 of an onion","Salt & pepper","#2 can tomatoes","#2 1/2 can chili beans","1 tsp. chili powder","Hot sauce or pepper, as desired"]}],"directions":[{"heading":null,"items":["Brown hamburger and onion in skillet. Add salt & pepper.","Mix all together. Simmer slowly.","Add hot sauce or pepper as desired.","Cook very slowly."]}],"notes":["From Brother Goodman."],"images":[{"file":"0094-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chocolate-cake","title":"Chocolate Cake","from":null,"card":"0075","tags":["cake","dessert","chocolate","cocoa","buttermilk","butter","frosting","chocolate frosting","baking"],"ingredients":[{"heading":null,"items":["[1/2?] cup cocoa","2 cups boiling water","4 tsp soda","4 cups sugar","[1 1/2?] cup butter","6 eggs","2 cups buttermilk","5 cups flour","[2?] tsp vanilla"]},{"heading":"Frosting","items":["4 cups sugar","2 tsp cream of tartar","4 tbsp cocoa","4 eggs","4 sticks butter","2 tsp vanilla"]}],"directions":[{"heading":null,"items":["Mix cocoa, boiling water and soda & let stand for 30 min.","Mix sugar, butter and eggs.","Add buttermilk, flour and vanilla.","Bake 400 for 20 min."]},{"heading":"Frosting","items":["Stir while bringing to boil (soft).","Mix with mixer until stiff."]}],"notes":["These amounts make a double batch: the card is headed \"2 Recipes of Chocolate Cake\" and the frosting \"Frosting — Double recipe\".","Other versions are on cards 0063 and 0129."],"images":[{"file":"0075-b.jpg","label":"Front"},{"file":"0075-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"chocolate-cookies","title":"Chocolate Cookies","from":"Muriel Jacob","card":"0087","tags":["cookies","dessert","chocolate","chocolate chips","sweetened condensed milk","eagle brand","pecans","walnuts","nuts","baking"],"ingredients":[{"heading":null,"items":["1 cube butter","3 Tbsp. sugar","1 can Borden's Eagle Brand milk","1 - 12 oz. pkg. chocolate chips","1 c. flour","1 tsp. vanilla","1 c. ground pecans or walnuts"]}],"directions":[{"heading":null,"items":["Put butter, sugar, chocolate chips and Eagle Brand milk in top of double boiler. Stir until melted.","Remove from fire and add the flour, vanilla & nuts.","Mix well & drop by teaspoonful on greased cookie sheet.","Bake at 350° for 8-10 min."]}],"notes":["From Muriel Jacob, who signed the back of the card.","Makes 60 cookies.","Beside the nuts: \"(I use pecans)\"."],"images":[{"file":"0087-b.jpg","label":"Front"},{"file":"0087-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"chocolate-cupcakes","title":"Chocolate Cupcakes","from":null,"card":"0148","tags":["cupcakes","cake","dessert","chocolate","cocoa","hershey's","buttermilk","powdered sugar","light","low-fat","baking"],"ingredients":[{"heading":null,"items":["6 tablespoons light corn oil spread","1 cup sugar","1 1/4 cups all-purpose flour","1/3 cup Hershey's Cocoa","1 teaspoon baking soda","Dash salt","1 cup lowfat buttermilk","1/2 teaspoon vanilla extract","Powdered sugar"]}],"directions":[{"heading":null,"items":["Heat oven to 350°. Line muffin pans with paper bake cups (2 1/2 inches in diameter).","In medium saucepan, melt corn oil spread. Remove from heat; stir in sugar.","Combine flour, cocoa, baking soda and salt; add alternately with buttermilk and vanilla to mixture in saucepan. Beat with whisk until well blended.","Spoon into bake cups. Bake 18 to 20 minutes or until wooden pick inserted in center comes out clean.","Remove from pans to wire rack; cool completely. Sift powdered sugar over top."]}],"notes":["From a Hershey's Cocoa label leaflet, \"The Lean Way to Make it Chocolate! 8 Light & Luscious Recipes.\"","Makes 18 cupcakes. Per serving: 110 calories, 0 mg cholesterol, 3 g fat.","Also on the same label: Hershey's Light Chocolate Cake, Creamy Chocolate and Peach Layered Pudding, Silky Cocoa Creme, Fruit-Filled Chocolate Dreams, Chocolate Ricotta Cheesecake."],"images":[{"file":"0148-b.jpg","label":"Front"},{"file":"0148-a.jpg","label":"Back"}],"sameCard":["fruit-filled-chocolate-dreams","chocolate-ricotta-cheesecake","hersheys-light-chocolate-cake","creamy-chocolate-and-peach-layered-pudding","silky-cocoa-creme"]},{"slug":"chocolate-pie","title":"Chocolate Pie","from":null,"card":"0085","tags":["pie","dessert","chocolate","cocoa","cornstarch","milk","eggs","meringue","vanilla"],"ingredients":[{"heading":null,"items":["2 tbs. cocoa","2 tbs. cornstarch","2 cups milk","1 cup sugar","3 egg yolks","1 tbs. vanilla"]}],"directions":[{"heading":null,"items":["Save whites & beat for top of pie."]}],"notes":["Added at the top of the card: \"Crust 375 15 min\" (bake the crust at 375° for 15 minutes)."],"images":[{"file":"0085-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"chocolate-ricotta-cheesecake","title":"Chocolate Ricotta Cheesecake","from":null,"card":"0148","tags":["cheesecake","dessert","chocolate","cocoa","hershey's","ricotta","yogurt","graham cracker","egg whites","light","low-fat","baking"],"ingredients":[{"heading":null,"items":["1/3 cup graham cracker crumbs","3 1/2 cups part-skim ricotta cheese, drained","Yogurt cheese* (made from 16-oz. container vanilla lowfat yogurt, no gelatin added)","2 egg whites","3/4 cup sugar","1/3 cup Hershey's Cocoa","2 tablespoons all-purpose flour","2 teaspoons vanilla extract"]}],"directions":[{"heading":null,"items":["Heat oven to 325°. Sprinkle crumbs on bottom of 9-inch springform pan.","In food processor bowl or large mixer bowl, process ricotta cheese until smooth.","Add yogurt cheese, egg whites, sugar, cocoa, flour and vanilla; process just until well blended. Pour over crumbs.","Bake 50 minutes or until edges are set. Turn off oven; open door slightly. Leave cheesecake in oven 1 hour.","Remove from oven. Cool; refrigerate until thoroughly chilled."]},{"heading":"Yogurt Cheese","items":["*To make yogurt cheese: Line a non rusting colander or sieve with a large piece of double thickness cheesecloth; place colander over a deep bowl.","Spoon yogurt into prepared colander; cover. Refrigerate until liquid no longer drains from yogurt, about 24 hours.","Remove yogurt from cheesecloth; discard liquid."]}],"notes":["From a Hershey's Cocoa label leaflet, \"The Lean Way to Make it Chocolate! 8 Light & Luscious Recipes.\"","16 servings. Per serving: 160 calories, 20 mg cholesterol, 5 g fat.","Also on the same label: Hershey's Light Chocolate Cake, Creamy Chocolate and Peach Layered Pudding, Silky Cocoa Creme, Fruit-Filled Chocolate Dreams, Chocolate Cupcakes."],"images":[{"file":"0148-b.jpg","label":"Front"},{"file":"0148-a.jpg","label":"Back"}],"sameCard":["fruit-filled-chocolate-dreams","chocolate-cupcakes","hersheys-light-chocolate-cake","creamy-chocolate-and-peach-layered-pudding","silky-cocoa-creme"]},{"slug":"chocolate-thru-and-thru-cake","title":"Chocolate Thru & Thru Cake","from":null,"card":"0129","tags":["cake","dessert","chocolate","cocoa","buttermilk","frosting","chocolate frosting","baking"],"ingredients":[{"heading":"Cake","items":["1/4 cup cocoa","1 cup boiling water","2 tsp. soda","2 cups sugar","2/3 cup shortening","3 eggs","1 cup buttermilk","2 1/2 cups flour","1 tsp. vanilla"]},{"heading":"Frosting","items":["2 cups sugar","1 tsp. cream of tartar","2 Tblsp. cocoa","2 eggs","1/2 lb. (2 sticks) butter","1 tsp. vanilla"]}],"directions":[{"heading":"Cake","items":["Mix cocoa, boiling water and soda and let stand for 30 minutes (mix by hand).","Mix (electric mixer) sugar, shortening, eggs, buttermilk, flour and vanilla.","Bake @ 400° for 20 min."]},{"heading":"Frosting","items":["Either cook in a double boiler for 30 minutes or slowly over burner, stirring constantly.","After cooking 30 minutes, mix with electric mixer until stiff."]}],"notes":["Written on a \"NOTES\" notepad sheet with red heart-shaped music notes.","Other versions are on cards 0063 and 0075."],"images":[{"file":"0129-b.jpg","label":"Front"},{"file":"0129-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"chocolate-topped-brown-sugar-bars","title":"Chocolate-Topped Brown Sugar Bars","from":null,"card":"0146","tags":["bars","cookies","candy","dessert","butter","brown sugar","egg white","flour","chocolate","hershey's","baking"],"ingredients":[{"heading":null,"items":["1 c butter","1 c brown sugar","1 egg white","1 c flour","6 Hershey's chocolate bars"]}],"directions":[{"heading":null,"items":["Cream butter, brown sugar and egg white. Add flour.","Put into a greased big flat baking pan (15 x 10). Cook 15-20 minutes at 350°.","When it comes out hot, lay 6 Hershey's chocolate bars on top and spread them over it as they soften.","Let cool, then break into pieces."]}],"notes":["Another version is on card 0131 (Skor)."],"images":[{"file":"0146-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"cinnamon-apple-salad","title":"Cinnamon Apple Salad","from":null,"card":"0050","tags":["salad","gelatin","jello","strawberry","cinnamon candies","red hots","apple","celery","nuts","cottage cheese","meadow gold","molded salad"],"ingredients":[{"heading":null,"items":["2/3 cup red cinnamon candies","2 cups boiling water","1 pkg. (6 oz.) strawberry flavored gelatin","2 cups cold water","2 cups (16 oz.) Meadow Gold Cottage Cheese","1 1/2 cups diced apples","1 1/2 cups chopped celery","3/4 cup chopped nuts"]}],"directions":[{"heading":null,"items":["Dissolve cinnamon candies in boiling water; pour over gelatin and stir until dissolved.","Add cold water; chill until partially thickened.","Fold in cottage cheese, apples, celery and nuts.","Spoon mixture into individual salad molds. Chill until firm.","Unmold on crisp salad greens. Serve with Meadow Gold Mayonnaise or Salad Dressing."]}],"notes":["From a Meadow Gold dairy recipe.","Makes 10–12 servings."],"images":[{"file":"0050-b.jpg","label":"Front"},{"file":"0050-a.jpg","label":"Back"}],"sameCard":["chiffon-cake-0050"]},{"slug":"cinnamon-rolls","title":"Cinnamon Rolls","from":"Viki Love","card":"0105","tags":["cinnamon rolls","rolls","bread","breakfast","dessert","yeast","flour","milk","butter","brown sugar","raisins","nuts","baking"],"ingredients":[{"heading":null,"items":["1 1/2 c. flour","1/3 c. sugar","1 tsp. salt","2 TBp yeast","1 c. scalded milk","1/2 c. water","1/4 c. melted butter","1/2 cup flour","1 egg","2 cups flour"]},{"heading":"Cinnamon Mixture","items":["1 stick of butter, softened","1 c. brown sugar","Optional: raisins, nuts"]}],"directions":[{"heading":null,"items":["Place 1 1/2 c. flour, sugar, salt and yeast in a mixing bowl & stir.","Pour scalded milk, water and melted butter to dry ingredients and add 1/2 cup flour and 1 egg. Mix.","Gradually add 2 cups of flour; knead/stir.","Let rise 15-20 minutes.","Roll out on lightly floured surface.","Spread with cinnamon mixture.","Roll up dough and cut in circles.","Place in greased pan.","Let rise till doubled (20 min).","Bake 15-20 min. at 400°; cooking time varies."]}],"notes":["From Viki, headed \"Cinnamon Rolls - mmm good!\" and ending \"Enjoy\" with a smiley face."],"images":[{"file":"0105-b.jpg","label":"Front"},{"file":"0105-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"coconut-crust","title":"Coconut Crust Pie","from":null,"card":"loose-11","tags":["pie","dessert","coconut","pineapple","gelatin","eggs"],"ingredients":[{"heading":"Crust","items":["2 cans (3 1/2 oz. each) flaked coconut","1/4 cup melted butter or margarine"]},{"heading":"Filling","items":["1/2 cup water plus pineapple juice","2 envelopes unflavored gelatin","1/2 cup sugar","1/8 tsp. salt","3 eggs, separated"]}],"directions":[{"heading":"Crust","items":["Combine coconut and butter. Toss with a fork until the coconut is evenly moist.","Press against the sides of a 9\" pie pan. Bake at 300° for 35–40 minutes."]},{"heading":"Filling","items":["Measure liquid into a saucepan; sprinkle in gelatin. Let stand 1 minute.","Add half the sugar and all the salt, and [beat?].","Stir over low heat until gelatin is dissolved."]}],"notes":["A neatly printed copy of the recipe was kept with the cursive original."],"images":[{"file":"loose-12.jpg","label":"Original (cursive)"},{"file":"loose-11.jpg","label":"Printed copy"}],"sameCard":[]},{"slug":"coleslaw-relish","title":"Coleslaw Relish","from":null,"card":"0020","tags":["relish","canning","preserves","condiment","cabbage","onion","green pepper","red pepper","vinegar","celery seed"],"ingredients":[{"heading":null,"items":["16 cups finely shredded green cabbage (about 4 pounds)","4 cups chopped onions (4 large)","1 cup diced sweet green pepper","1 cup diced sweet red pepper","2/3 cup salt","2 cups sugar","1 tsp. celery seeds","2 cups white vinegar"]}],"directions":[{"heading":null,"items":["Mix cabbage, onions, green and red peppers, and salt in a large bowl. Pour in ice water to cover; cover. Let stand overnight.","Drain vegetables well; pack into hot sterilized jars.","Combine sugar, celery seeds, and vinegar in a medium-size saucepan; heat, stirring constantly, to boiling.","Pour into jars to fill to rim; seal, following manufacturer's directions. Cool jars, label, and date."]}],"notes":["\"Cabbage stays refreshingly crisp and has a tart, tangy flavor.\"","Makes 12 eight-ounce jars or 6 sixteen-ounce jars."],"images":[{"file":"0020-a.jpg","label":"Front"},{"file":"0020-b.jpg","label":"Back"}],"sameCard":[]},{"slug":"corn-beef-and-cabbage","title":"Corn Beef and Cabbage","from":null,"card":"0007","tags":["main dish","one-pot","corned beef","canned corned beef","cabbage","carrots","celery","onion","tomato sauce"],"ingredients":[{"heading":null,"items":["Cabbage","Onion","Canned corn beef","Chopped celery","Carrots (4-5), quartered","Can tomato sauce","1 can water","Salt and pepper"]}],"directions":[{"heading":null,"items":["Cut cabbage in 1/4's.","Simmer onion and canned corn beef.","Add chopped celery and quartered carrots (4-5).","Add can tomato sauce and 1 can water.","Add cabbage, salt and pepper. Cover and let boil. Simmer until tender."]}],"notes":[],"images":[{"file":"0007-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"corn-meal-recipe","title":"Corn Meal Recipe","from":null,"card":"0070","tags":["bread","cornbread","corn sticks","side dish","corn meal","milk","eggs","baking"],"ingredients":[{"heading":null,"items":["1 cup corn meal","1/3 cup flour","1/2 tsp. salt","2 tsp. baking powder","1 cup milk","1 egg beaten","3 Tbsp. cooking oil","1 Tbsp. sugar"]}],"directions":[{"heading":null,"items":["Mix dry ingredients in a bowl. Add milk and egg, stir together.","Add cooking oil or melted shortening and thoroughly mix.","Pour into an 8 inch round cake pan and bake at 450° F. for 20 to 25 minutes.","For corn sticks use same recipe and be sure pan is hot before pouring in batter."]}],"notes":["Also headed \"Cornbread\" on the card."],"images":[{"file":"0070-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"corn-pone-for-dressing-0099","title":"Corn Pone for Dressing","from":null,"card":"0099","tags":["dressing","stuffing","side dish","cornbread","corn pone","cornmeal","turkey","sage","eggs","celery","onion","thanksgiving","baking"],"ingredients":[{"heading":"Corn Pone","items":["[3?] cups corn meal","3 cups flour","2 tsp. salt","8 tsp. baking powder","4 1/2 cups milk","1/4 cup cooking oil","1/2 cup sugar","4 large eggs","1 1/2 tbs. sage"]},{"heading":"Dressing","items":["Broth from turkey","Onion","Celery","Eggs"]}],"directions":[{"heading":"Corn Pone","items":["Bake @ 425° 1 hour."]},{"heading":"Dressing","items":["Add to broth from turkey.","Sauté onion, celery. Add eggs."]}],"notes":["Another version is on card 0097, which adds a gravy, amounts for a larger batch, and fuller dressing steps."],"images":[{"file":"0099-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"corn-pone-for-dressing","title":"Corn Pone for Dressing","from":null,"card":"0097","tags":["dressing","stuffing","side dish","cornbread","corn pone","cornmeal","turkey","chicken","sage","eggs","celery","onion","gravy","thanksgiving","make-ahead","baking"],"ingredients":[{"heading":"Corn Pone","items":["[3?] cups corn meal","3 cups flour","2 tsp. salt","8 tsp. baking powder","4 1/2 cups milk","1/4 cup cooking oil","1/2 cup sugar","4 large eggs","1 1/2 Tbs. sage"]},{"heading":"Dressing","items":["Turkey broth or chicken broth","Onions and celery","Butter","4 chopped boiled eggs"]},{"heading":"Gravy","items":["Broth from turkey","Water","4 heaping tablespoons flour","1 cup milk (or cream)","Salt & pepper to taste"]}],"directions":[{"heading":"Corn Pone","items":["Bake @ 425° 1 hour. Can bake ahead of time."]},{"heading":"Dressing","items":["Add turkey broth or chicken broth.","Sauté onions & celery in butter.","Add 4 chopped boiled eggs to corn pone already cooked.","Heat before serving."]},{"heading":"Gravy","items":["Make paste with water & flour (4 heaping tablespoons flour, mixed to a paste).","Add to hot broth & boil.","Add milk or cream (1 cup milk). Salt & pepper to taste."]}],"notes":["Also headed \"Corn pone for dressing turkey or chicken.\"","Amounts for a larger batch (marked \"20\") are written in a column beside the ingredients: 4, 4, 3, 12, (scribbled out), [6?], 3/4, 6, [1 1/2?].","Another version is on card 0099."],"images":[{"file":"0097-b.jpg","label":"Front"},{"file":"0097-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"creamy-chocolate-and-peach-layered-pudding","title":"Creamy Chocolate and Peach Layered Pudding","from":null,"card":"0148","tags":["pudding","dessert","chocolate","cocoa","hershey's","peaches","fruit","milk","cornstarch","light","low-fat","microwave"],"ingredients":[{"heading":null,"items":["1/3 cup sugar","1/4 cup Hershey's Cocoa","3 tablespoons cornstarch","2 2/3 cups 2% lowfat milk","1 teaspoon vanilla extract","Peach Sauce (recipe follows)"]},{"heading":"Peach Sauce","items":["1/4 cup water","1 1/2 teaspoons cornstarch","1 1/2 cups fresh peaches, pureed","1 tablespoon sugar"]}],"directions":[{"heading":null,"items":["In medium saucepan, stir together sugar, cocoa and cornstarch; gradually stir in milk.","Cook over medium heat, stirring constantly until mixture comes to a boil; boil 1 minute.","Remove from heat; stir in vanilla. Press plastic wrap directly onto surface. Cool.","Meanwhile, prepare Peach Sauce.","In dessert dishes, layer chocolate pudding and Peach Sauce. Refrigerate until chilled."]},{"heading":"Peach Sauce","items":["In small microwave-safe bowl, stir together water and cornstarch until smooth.","Add peaches and sugar; stir.","Microwave at HIGH (100%) 2 1/2 to 3 minutes or until mixture boils, stirring after each minute. Cool."]}],"notes":["From a Hershey's Cocoa label leaflet, \"The Lean Way to Make it Chocolate! 8 Light & Luscious Recipes.\"","6 servings. Peach Sauce makes about 1 1/3 cups. Per serving: 180 calories, 10 mg cholesterol, 5 g fat."],"images":[{"file":"0148-b.jpg","label":"Front"},{"file":"0148-a.jpg","label":"Back"}],"sameCard":["fruit-filled-chocolate-dreams","chocolate-cupcakes","chocolate-ricotta-cheesecake","hersheys-light-chocolate-cake","silky-cocoa-creme"]},{"slug":"creamy-honey-frosting","title":"Creamy Honey Frosting","from":null,"card":"0027","tags":["frosting","icing","cake","dessert","honey","confectioners' sugar","shortening","vanilla"],"ingredients":[{"heading":null,"items":["2 Tbsp. shortening","1 1/2 cups confectioners' sugar (sift if lumpy)","1/4 tsp. salt","1/2 tsp. vanilla","2 Tbsp. honey","1 Tbsp. milk"]}],"directions":[{"heading":null,"items":["Combine shortening, salt, vanilla, and 1/2 cup sugar.","Add remaining sugar and honey and milk alternately, mixing until smooth and creamy.","Add more sugar to thicken or milk to thin frosting, if required, until of spreading consistency. Spread on cake."]}],"notes":[],"images":[{"file":"0027-b.jpg","label":"Front"},{"file":"0027-a.jpg","label":"Back"}],"sameCard":["butterscotch-sauce","magic-topping"]},{"slug":"custard-and-meringue","title":"Custard and Meringue","from":null,"card":"0139","tags":["custard","pudding","pie filling","cream pie","meringue","dessert","eggs","milk","sugar","butter"],"ingredients":[{"heading":"Custard","items":["4 egg yolks","1/2 tsp. salt","3/4 c. sugar","2 cups milk","2 tbs. flour + a little water","1 tbs. butter"]},{"heading":"Meringue","items":["4 egg whites","1/3 c. sugar"]}],"directions":[{"heading":"Custard","items":["No directions for the custard on the card."]},{"heading":"Meringue","items":["Froth the 4 whites; add 1/3 c. sugar."]}],"notes":[],"images":[{"file":"0139-b.jpg","label":"Front"},{"file":"0139-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"double-chocolate-cake","title":"Double Chocolate Cake","from":null,"card":"0063","tags":["cake","dessert","chocolate","cocoa","buttermilk","icing","baking"],"ingredients":[{"heading":null,"items":["1/2 cup cocoa","2 cups boiling water","4 tsp. soda","4 cups sugar","1 1/2 cups butter","6 eggs","2 cups buttermilk","5 cups flour","2 tsp. vanilla"]},{"heading":"Icing for Cake","items":["4 cups sugar","2 tsp. cream of tartar","4 Tbsp. cocoa","4 eggs","1 lb. butter","2 tsp. vanilla"]}],"directions":[{"heading":null,"items":["Mix cocoa, boiling water and soda, and let stand.","Bake at 400° for 20 minutes."]},{"heading":"Icing for Cake","items":["Cook, stirring, until boiling, then until thick.","Pour immediately on cake. Spread with spoon."]}],"notes":["Other versions are on cards 0075 and 0129."],"images":[{"file":"0063-b.jpg","label":"Front"},{"file":"0063-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"doughnuts","title":"Doughnuts","from":null,"card":"0019","tags":["doughnuts","dessert","breakfast","yeast","fried","powdered sugar","shortening"],"ingredients":[{"heading":null,"items":["1/2 cup shortening (melted)","1/2 cup boiling water","1/2 tsp. salt","3 Tbsp. sugar","1/2 cup cold water","1 pkg. yeast","1 egg","3 cups flour"]}],"directions":[{"heading":null,"items":["Mix the shortening, boiling water, salt and sugar, and add the cold water, yeast, egg and flour.","Let rise and punch down; let rise and roll out; let rise double and fry.","Dip in powdered sugar mixture."]}],"notes":[],"images":[{"file":"0019-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"egg-sauce-for-lettuce-or-cabbage","title":"Egg Sauce for Lettuce or Cabbage","from":null,"card":"0028","tags":["sauce","salad dressing","dressing","eggs","sugar","vinegar","cream","lettuce","cabbage","salad"],"ingredients":[{"heading":null,"items":["4 Tb. sugar","2 eggs","2 Tb. vinegar","Sweet cream"]}],"directions":[{"heading":null,"items":["Cook til thick.","Add sweet cream; mix and serve on lettuce."]}],"notes":[],"images":[{"file":"0028-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"ezekiel-bread","title":"Ezekiel Bread","from":null,"card":"0130","tags":["bread","yeast bread","wheat","rye","barley","millet","beans","lentils","honey","corn oil","whole grain","baking"],"ingredients":[{"heading":null,"items":["Wheat 2 1/2 c.","Rye 1 1/2 c.","Barley 1/2 c.","Millet 1/4 c.","Great Northern beans - 2 T.","Pinto beans - 2 T.","Kidney beans - 2 T.","Lentils - 1/4 c.","2 t. salt","1 1/4 c. warm water","3 T. yeast","1 t. honey","1/2 c. corn oil","1/2 c. honey","1 c. warm water"]}],"directions":[{"heading":null,"items":["Mix the 1 1/4 c. warm water, yeast and 1 t. honey and let set until bubbly.","After the above bubbles, add the corn oil and 1/2 c. honey.","Now mix with dry ingredients, then add 1 c. warm water to all ingredients mixed together.","Let rise in a pan 1 hr.","Bake at 350° for 30 min. (Pat onto 2 cookie sheets with sides on them.)"]}],"notes":[],"images":[{"file":"0130-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"finest-cherry-pie","title":"Finest Cherry Pie","from":null,"card":"0003","tags":["pie","dessert","cherry","almond","lemon","baking"],"ingredients":[{"heading":null,"items":["Pastry for a 2-crust 9-inch pie","1 Tbsp. sugar","1 Tbsp. cake flour","1 can (No. 303) Stokely's Finest Red Tart Pitted Cherries","1 cup sugar","1/4 cup cake flour","1/8 tsp. salt","1/4 tsp. almond extract","1 tsp. lemon juice","1 Tbsp. butter"]}],"directions":[{"heading":null,"items":["Line a 9-inch pie pan with pastry. Sprinkle with 1 Tbsp. sugar and 1 Tbsp. cake flour.","Drain cherries, saving the juice.","Combine sugar, flour and salt. Gradually stir in cherry juice. Add almond extract and lemon juice.","Combine with cherries and pour into pastry-lined pan. Dot with butter. Put top crust in place.","Bake 30 to 35 minutes at 425°."]}],"notes":["This recipe is for the 1-lb. size can."],"images":[{"file":"0003-b.jpg","label":"Front"},{"file":"0003-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"flour-tortillas","title":"Flour Tortillas","from":null,"card":"0141","tags":["bread","tortillas","flour tortillas","mexican","new mexican","flour","shortening"],"ingredients":[{"heading":null,"items":["2 cups flour","1 tsp baking powder","1/8 tsp soda","1 tsp salt","3 tbsp shortening"]}],"directions":[{"heading":null,"items":["No directions on the card."]}],"notes":["Written on the back of a sheet of NMJC TRiO Programs letterhead (Hobbs, NM)."],"images":[{"file":"0141-a.jpg","label":"Front"},{"file":"0141-b.jpg","label":"Back"}],"sameCard":["sopaipillas-0141"]},{"slug":"fresh-fruit-pie","title":"Fresh Fruit Pie","from":null,"card":"0011","tags":["pie","dessert","fruit","fresh fruit","pie filling","butter","baking"],"ingredients":[{"heading":null,"items":["3/4 to 1 1/3 cup sugar","5 tbs flour","3 1/4 to 4 cups fruit","Butter"]}],"directions":[{"heading":null,"items":["The card gives no directions for this pie."]}],"notes":["The Canned Fruit Pie written below it on the same card says \"Bake 425°\"."],"images":[{"file":"0011-b.jpg","label":"Front"},{"file":"0011-a.jpg","label":"Back"}],"sameCard":["canned-fruit-pie","lemon-parfait-pie-and-fruit"]},{"slug":"frosted-orange-crush","title":"Frosted Orange Crush","from":null,"card":"0045","tags":["drink","beverage","orange","banana","pineapple","pineapple juice","sherbet","frozen"],"ingredients":[{"heading":null,"items":["1 ripe banana, mashed","3 cups Orange Drink","1 cup unsweetened pineapple juice","1 pint Orange Sherbet"]}],"directions":[{"heading":null,"items":["Beat together banana, orange drink and pineapple juice until well blended.","Freeze until slushy.","Beat in orange sherbet. Pour into glasses."]}],"notes":["Makes 4 servings (about 6 cups)."],"images":[{"file":"0045-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"frosted-salad","title":"Frosted Salad","from":null,"card":"0001","tags":["salad","dessert","gelatin","lemon","pineapple","banana","marshmallow","whipped cream","cheese","make-ahead"],"ingredients":[{"heading":null,"items":["2 pkgs. lemon flavored gelatin","2 cups boiling water","2 cups clear carbonated beverage","1 can ([20?] oz.) crushed pineapple","1 cup miniature marshmallows","2 large bananas, sliced","Whipped cream topping (below)"]},{"heading":"Topping","items":["1/2 cup sugar","2 Tbsp. flour","1 cup pineapple juice","1 egg, slightly beaten","2 Tbsp. butter","1 cup whipping cream, whipped","1/4 cup shredded American cheese","3 Tbsp. grated Parmesan cheese"]}],"directions":[{"heading":null,"items":["Dissolve gelatin in boiling water. Stir in carbonated beverage. Chill until partly set. Drain pineapple, saving the juice for the topping.","Fold pineapple, marshmallows and bananas into gelatin. Pour into a 9-inch springform pan or 7 x 12\" oblong dish. Chill until firm. Add topping. Chill overnight."]},{"heading":"Topping","items":["Combine sugar and flour. Stir in pineapple juice and egg. Cook over low heat until thickened.","Remove from heat; add butter. Let cool; chill.","Fold into whipped cream. Frost gelatin mixture. Sprinkle with cheese. Chill overnight."]}],"notes":[],"images":[{"file":"0001-b.jpg","label":"Front"},{"file":"0001-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"frozen-cranberry-salad-0077","title":"Frozen Cranberry Salad","from":null,"card":"0077","tags":["salad","frozen salad","dessert","cranberry","apricots","peaches","apples","pineapple","pecans","whipped cream","holiday","make-ahead"],"ingredients":[{"heading":null,"items":["1 qt fresh cranberries","2 1/2 cups sugar","1 apricots (large can), drain juice","1 peaches (large can), drain juice","4 cup fresh apples","1 can crushed pineapple","3 cups pecans","1 pt whipped cream"]}],"directions":[{"heading":null,"items":["Grind cranberries and sugar in food chopper & let stand overnight.","Add after grinding: apricots, peaches, apples, crushed pineapple and pecans.","Mix all ingredients together & fold in whipped cream.","Freeze."]}],"notes":["Written on a \"From My Kitchen\" recipe card with a picture of a roast turkey, ham and a pot of beans.","Another version is on card 0106."],"images":[{"file":"0077-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"frozen-cranberry-salad","title":"Frozen Cranberry Salad","from":null,"card":"0106","tags":["salad","frozen salad","dessert","cranberry","apricot","peach","apple","pineapple","pecans","whipped cream","make-ahead"],"ingredients":[{"heading":null,"items":["1 qt. fresh cranberries","2 1/2 cups sugar","1 large can apricots, drain juice","1 large can peaches, drain juice","4 fresh apples","1 can crushed pineapple","3 cups pecans, chopped","1 pint whip cream"]}],"directions":[{"heading":null,"items":["Grind cranberries and sugar in food chopper; let stand overnight.","After grinding, add apricots, peaches and apples.","Then add crushed pineapple and pecans, and fold in whip cream. Then [freeze?]."]}],"notes":["Another version is on card 0077."],"images":[{"file":"0106-b.jpg","label":"Front"},{"file":"0106-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"frozen-salad","title":"Frozen Salad","from":null,"card":"0026","tags":["salad","frozen salad","dessert","cream cheese","fruit cocktail","fruit salad","marshmallow","nuts","make-ahead"],"ingredients":[{"heading":null,"items":["1 Phil. cream cheese","1 large can fruit salad, with its juice","Cut marshmallows","Nuts"]}],"directions":[{"heading":null,"items":["Combine cream cheese and the juice of the fruit salad.","Add fruit salad, cut marshmallows, and nuts.","Pour into ice cube tray and freeze."]}],"notes":["\"Phil.\" is Philadelphia cream cheese."],"images":[{"file":"0026-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"fruit-pemmican","title":"Fruit Pemmican","from":null,"card":"0115","tags":["snack","candy","no-bake","dried fruit","apricots","raisins","coconut","prunes","apples","dates","walnuts","nuts","honey","peanut butter"],"ingredients":[{"heading":null,"items":["1 c. dried apricots","1 c. raisins","1 c. coconut, shredded fine","1/2 c. dried prunes","1 c. dried apples","1 c. chopped nuts (walnuts)","1/2 c. dates","1/2 c. honey","1/2 c. peanut butter","Water, if needed"]}],"directions":[{"heading":null,"items":["Put all ingredients through a food grinder at least twice.","Blend in honey & peanut butter (if needed, 1 T. water at a time) until it has the consistency of very hard dough.","Roll out in a thin roll; twist and cut in bite-sized pieces."]}],"notes":["Written on the same red saltbox-house recipe card, in the same hand, as Mom's Applesauce Cake (card 0114)."],"images":[{"file":"0115-b.jpg","label":"Front"},{"file":"0115-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"fruit-filled-chocolate-dreams","title":"Fruit-Filled Chocolate Dreams","from":null,"card":"0148","tags":["dessert","frozen dessert","chocolate","cocoa","hershey's","whipped topping","fruit","chocolate sauce","sauce","light","low-fat"],"ingredients":[{"heading":null,"items":["1/2 cup cold skim milk","1 envelope (1.3 oz.) whipped topping mix","1/2 teaspoon vanilla extract","1 tablespoon Hershey's Cocoa","Assorted fresh fruit, cut up","Chocolate Sauce (below)"]},{"heading":"Chocolate Sauce","items":["3/4 cup sugar","1/3 cup Hershey's Cocoa","1 Tbls. cornstarch","3/4 cup water","1 Tbls. margarine","1 tsp. vanilla"]}],"directions":[{"heading":null,"items":["Place foil on cookie sheet.","In small mixer bowl, blend milk, topping mix, vanilla and cocoa. Whip at high speed of electric mixer until topping peaks, about 2 minutes. Continue beating 2 minutes longer until topping is light and fluffy.","Spoon mixture into five mounds onto prepared cookie sheet. With spoon, shape into 4-inch shells. Freeze.","To serve, fill center of each frozen shell with fruit; drizzle with Chocolate Sauce. Serve immediately."]},{"heading":"Chocolate Sauce","items":["In small sauce pan, combine sugar, cocoa and cornstarch; stir in water.","Cook over medium heat, stirring constantly, until mixture comes to a boil; boil 1 minute.","Remove from heat; add margarine and vanilla, stirring until smooth. Refrigerate."]}],"notes":["From a Hershey's Cocoa label leaflet, \"The Lean Way to Make it Chocolate! 8 Light & Luscious Recipes.\"","5 servings. Chocolate Sauce makes about 1 cup. Per serving: 130 calories, 0 mg cholesterol, 1 g fat."],"images":[{"file":"0148-b.jpg","label":"Front"},{"file":"0148-a.jpg","label":"Back"}],"sameCard":["chocolate-cupcakes","chocolate-ricotta-cheesecake","hersheys-light-chocolate-cake","creamy-chocolate-and-peach-layered-pudding","silky-cocoa-creme"]},{"slug":"fudge-0101","title":"Fudge","from":null,"card":"0101","tags":["candy","fudge","dessert","chocolate","cocoa","cheese","american cheese","oleo","powdered sugar","pecans","nuts"],"ingredients":[{"heading":null,"items":["1 lb. processed American cheese (cubed)","1 lb. oleo","1 tbs. vanilla","1 cup cocoa","4 lb. powdered sugar","3 cup chopped pecans"]}],"directions":[{"heading":null,"items":["In heavy saucepan, melt cheese + oleo over low flame.","Stir in vanilla. Sift cocoa + powdered sugar; stir into cheese mixture until smooth.","Add pecans. Pour in buttered dish. Chill."]}],"notes":["Makes 7 lbs.","Oleo is margarine.","The back of the card says \"SALADS\", as if it once marked a section of the recipe box."],"images":[{"file":"0101-b.jpg","label":"Front"},{"file":"0101-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"fudge","title":"Fudge","from":null,"card":"0030","tags":["fudge","candy","dessert","chocolate","cocoa","sugar","milk","vanilla","karo","corn syrup","butter"],"ingredients":[{"heading":null,"items":["2 cups sugar","2 Tbsp cocoa per cup sugar (4 Tbsp)","1 cup milk","Dash salt","1 1/2 tsp vanilla"]}],"directions":[{"heading":null,"items":["Stir and cook until it gets thick, soft ball.","Turn out fire, add vanilla.","Beat until right consistency, pour in buttered dish.","Cut before completely hardened."]}],"notes":["Added in green ink in the margin: 2 Tbsp butter, 1/4 tsp cream of tartar, 2 Tbsp Karo.","Also added in green ink: \"Cool to lukewarm\" before beating."],"images":[{"file":"0030-b.jpg","label":"Front"},{"file":"0030-a.jpg","label":"Back"}],"sameCard":["orange-sauce"]},{"slug":"german-chocolate-cake","title":"German Chocolate Cake","from":null,"card":"0060","tags":["cake","dessert","chocolate","german's sweet chocolate","baker's chocolate","buttermilk","coconut","pecans","nuts","frosting","layer cake","baking"],"ingredients":[{"heading":null,"items":["1 pkg. Bakers German Sweet Choc.","1/2 cup boiling water","1 cup butter (shortening)","2 cups sugar","4 egg yolks, unbeaten","1 tsp. vanilla","2 1/2 cups cake flour","1 tsp. soda","1/2 tsp. salt","1 cup buttermilk","4 egg whites"]},{"heading":"Coconut Pecan Frosting","items":["1 cup evaporated milk","1 cup sugar","3 egg yolks","1/4 pound oleo","1 tsp. vanilla","1 1/3 cup coconut","1 cup chopped nuts"]}],"directions":[{"heading":null,"items":["Melt chocolate in 1/2 cup boiling water. Cool.","Cream butter and sugar until light and fluffy. Add egg yolks one at a time, beat well after each addition.","Add melted choc. and vanilla. Mix well.","Sift dry ingredients alternately with buttermilk to chocolate mixture. Beat until smooth.","Beat egg whites until stiff, peaks form. Fold into batter.","3 layers. Bake in 350° oven, 35–40 minutes."]},{"heading":"Coconut Pecan Frosting","items":["Combine evaporated milk, sugar, egg yolks, oleo and vanilla.","Cook and stir over medium heat until mixture thickens, about 12 minutes.","Add coconut and chopped nuts. Beat until cool and thick. Spread on tops."]}],"notes":[],"images":[{"file":"0060-b.jpg","label":"Front"},{"file":"0060-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"german-chocolate-pie","title":"German Chocolate Pie","from":null,"card":"0057","tags":["pie","dessert","chocolate","german's sweet chocolate","coconut","pecans","custard","cream pie","whipped cream"],"ingredients":[{"heading":null,"items":["3/4 cup sugar","1/2 cup flour","1/4 tsp. salt","2 cups milk","1 bar German's sweet chocolate (4 oz.)","3 egg yolks","2 Tbsp. margarine","1 tsp. \"Adams Best\" vanilla","1/2 tsp. Adams Butter flavoring","1 cup coconut (Angel Flake)","1/2 cup chopped pecans (coarse)","Baked 9\" pie shell","Whipped cream"]}],"directions":[{"heading":null,"items":["Combine sugar, flour, salt and 1/2 cup cold milk. Mix well.","Scald remaining milk and add chocolate. Stir until chocolate is melted.","Add scalded milk and chocolate to first mixture and cook until thickened.","Separate egg yolks; beat egg yolks slightly and add slowly to hot mixture, stirring constantly. Continue to cook over low heat about 2 or 3 minutes.","Remove from heat and add remaining ingredients.","Cool and pour into a baked 9\" pie shell. Chill and top with whipped cream."]}],"notes":[],"images":[{"file":"0057-a.jpg","label":"Front"},{"file":"0057-b.jpg","label":"Back"}],"sameCard":[]},{"slug":"german-chocolate-poundcake","title":"German Chocolate Poundcake","from":null,"card":"0031","tags":["cake","pound cake","dessert","chocolate","german chocolate","buttermilk","shortening","vanilla","butter flavor","baking"],"ingredients":[{"heading":null,"items":["2 cups sugar","1 cup shortening","4 eggs","2 tsp. \"Adams Best\" vanilla","2 tsp. Adams Butter Flavor (no calories)","1 cup buttermilk","3 cups sifted all purpose flour","1/2 tsp. soda","1 tsp. salt","1 pkg. German Sweet Chocolate"]}],"directions":[{"heading":null,"items":["Cream sugar and shortening and add eggs, flavors and buttermilk.","Sift together flour, soda and salt and add. Mix well.","Then add German Chocolate that has been softened in warm oven or in double boiler. Blend together well.","Cook in 9\" stem pan that has been well greased and dusted with flour, about 1 1/2 hours at 300°.","Remove cake from pan while still hot and place under a tight fitting cake cover and leave covered until cold."]}],"notes":["A \"stem pan\" is a tube pan."],"images":[{"file":"0031-b.jpg","label":"Front"},{"file":"0031-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"german-sweet-chocolate-cream-cheese-brownies","title":"German Sweet Chocolate Cream Cheese Brownies","from":null,"card":"0125","tags":["brownies","bars","dessert","chocolate","german sweet chocolate","cream cheese","nuts","baking"],"ingredients":[{"heading":"Brownie Layer","items":["1 package (4 oz.) Baker's German's Sweet Chocolate","1/4 cup (1/2 stick) margarine","3/4 cup sugar","2 eggs","1 teaspoon vanilla","1/2 cup all-purpose flour","1/2 cup chopped nuts (optional)"]},{"heading":"Cream Cheese Layer","items":["4 ounces Philadelphia Brand Cream Cheese, softened","1/4 cup sugar","1 egg","1 tablespoon all-purpose flour"]}],"directions":[{"heading":"Brownie Layer","items":["Heat oven to 350° F.","Microwave* chocolate and margarine in large microwavable bowl at HIGH 2 minutes or until margarine is melted. Stir until chocolate is completely melted.","Stir sugar into melted chocolate mixture. Stir in eggs and vanilla until completely mixed. Mix in flour until well blended. Stir in nuts. Spread in greased 8-inch square pan."]},{"heading":"Cream Cheese Layer","items":["In same bowl, mix cream cheese, sugar, egg and flour until smooth. Spoon over brownie mixture; swirl with knife to marbleize.","Bake for 35 minutes or until wooden pick inserted in center comes out with fudgy crumbs. (Do not overbake.) Cool in pan; cut into squares."]}],"notes":["From a Baker's \"One Bowl Recipe\" card.","*Saucepan preparation: Melt chocolate and margarine in 2-quart saucepan over very low heat; stir constantly just until melted. Remove from heat. Continue as above.","Makes 16 brownies."],"images":[{"file":"0125-b.jpg","label":"Front"},{"file":"0125-a.jpg","label":"Back"}],"sameCard":["german-sweet-chocolate-pie"]},{"slug":"german-sweet-chocolate-pie","title":"German Sweet Chocolate Pie","from":null,"card":"0125","tags":["pie","dessert","chocolate","german sweet chocolate","cream cheese","whipped topping","cool whip","crumb crust","frozen","no-bake"],"ingredients":[{"heading":null,"items":["1 package (4 ounces) Baker's German's Sweet Chocolate","1/3 cup milk","1 package (3 ounces) Philadelphia Brand Cream Cheese, softened","2 tablespoons sugar (optional)","3 1/2 cups (8 ounces) Cool Whip Whipped Topping, thawed","9-inch prepared crumb crust","Chocolate Shavings or Curls (optional)"]}],"directions":[{"heading":null,"items":["Microwave chocolate and 2 tablespoons of the milk in large microwavable bowl on HIGH 1 1/2 to 2 minutes or until chocolate is almost melted, stirring halfway through heating time. Stir until chocolate is completely melted.","Beat in cream cheese, sugar and the remaining milk until well blended. Refrigerate to cool, about 10 minutes.","Stir in whipped topping gently until smooth. Spoon into crust. Freeze until firm, about 4 hours. Garnish with Chocolate Shavings or Curls, if desired."]}],"notes":["From a Baker's \"One Bowl Recipe\" card.","Saucepan preparation: Heat chocolate and 2 tablespoons of the milk in saucepan over very low heat until chocolate is melted, stirring constantly. Remove from heat. Continue as above.","Makes 8 servings."],"images":[{"file":"0125-b.jpg","label":"Front"},{"file":"0125-a.jpg","label":"Back"}],"sameCard":["german-sweet-chocolate-cream-cheese-brownies"]},{"slug":"glamorous-toppings","title":"Glamorous Toppings","from":null,"card":"0046","tags":["topping","dessert","whipped topping","dream whip","coffee","chocolate","fruit","strawberries","pineapple","peanut brittle","peppermint","nutmeg","cinnamon","pumpkin pie"],"ingredients":[{"heading":"Coffee Topping","items":["Dream Whip","2 tsp. instant coffee","1 Tbsp. confectioners sugar"]},{"heading":"Chocolate Fluff","items":["Dream Whip","2 tsp. sugar","2 Tbsp. instant chocolate mix"]},{"heading":"Fruit Whip","items":["Dream Whip","1/4 cup diced or crushed fruit, such as strawberries or pineapple"]},{"heading":"Crunchy Topping","items":["Dream Whip","Crushed peanut brittle or peppermint candy"]},{"heading":"Spiced Topping","items":["Dream Whip","1/2 tsp. nutmeg or cinnamon"]}],"directions":[{"heading":"Coffee Topping","items":["Prepare Dream Whip, adding 2 tsp. instant coffee and 1 Tbsp. confectioners sugar to milk before whipping. Wonderful frozen, too."]},{"heading":"Chocolate Fluff","items":["Prepare Dream Whip, adding 2 tsp. sugar and 2 Tbsp. instant chocolate mix to milk before whipping. Leftover topping is delicious frozen."]},{"heading":"Fruit Whip","items":["Prepare Dream Whip and fold in 1/4 cup diced or crushed fruit, such as strawberries or pineapple."]},{"heading":"Crunchy Topping","items":["Fold crushed peanut brittle or peppermint candy into prepared Dream Whip."]},{"heading":"Spiced Topping","items":["Add 1/2 tsp. nutmeg or cinnamon to prepared Dream Whip. Wonderful on pumpkin pie."]}],"notes":["Five ways to flavor Dream Whip whipped topping."],"images":[{"file":"0046-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"golden-westerner","title":"Golden Westerner","from":null,"card":"0017","tags":["cake","pound cake","tube cake","dessert","butter","eggs","powdered sugar","imperial sugar","vanilla","lemon","baking"],"ingredients":[{"heading":null,"items":["3 sticks butter or margarine","1 1-lb. carton Imperial 10X Powdered Sugar","6 eggs","1 Imperial 10X Powdered Sugar carton full of sifted flour","1 tsp. lemon juice","1 Tbsp. vanilla"]}],"directions":[{"heading":null,"items":["Have eggs and butter at room temperature.","Cream butter; add Imperial 10X Powdered sugar; beat till fluffy.","Add eggs, one at a time; beat well after each addition.","Sift flour 3 times; add gradually to batter. Add flavorings and mix well.","Bake in 10\" greased and floured tube pan at 325° 1 1/2 hours.","Cool 4 minutes, then invert pan.","Wonderful served plain, with whipped cream, fruit or ice cream. If you wish, spoon Imperial 10X Powdered Sugar lightly into ridges on top of cake."]}],"notes":["Subtitled \"Big Cake ... little time\".","The flour is measured by refilling the empty powdered-sugar carton."],"images":[{"file":"0017-a.jpg","label":"Front"},{"file":"0017-b.jpg","label":"Back"}],"sameCard":[]},{"slug":"good-n-easy-pizza","title":"Good 'n Easy Pizza","from":null,"card":"0124","tags":["pizza","main dish","yeast dough","pepperoni","mozzarella","parmesan","cheese","tomato sauce","oregano","gold medal flour","red star yeast"],"ingredients":[{"heading":"Dough","items":["1 package Red Star active dry yeast","1 cup warm water (105 to 115°)","1 teaspoon sugar","1 teaspoon salt","2 tablespoons salad oil","2 1/2 cups Gold Medal flour*"]},{"heading":"Sauce","items":["1/2 cup chopped onion","1 can (8 ounces) tomato sauce","1/4 teaspoon salt","1/8 teaspoon instant minced garlic","1/8 teaspoon pepper"]},{"heading":"Topping","items":["1/4 cup grated Parmesan cheese","2 teaspoons oregano","1 cup sliced pepperoni (about 4 ounces)","2 cups shredded mozzarella cheese (about 8 ounces)"]}],"directions":[{"heading":"Dough","items":["Dissolve yeast in warm water. Stir in remaining Dough ingredients; beat vigorously, about 20 strokes. Allow Dough to rest (about 5 minutes) while preparing Sauce."]},{"heading":"Sauce","items":["Mix Sauce ingredients; set aside."]},{"heading":"Topping","items":["Heat oven to 425°. Divide Dough in half. On lightly greased baking sheets, pat each half into 10-inch circle. (Continue to flour fingers when patting Dough into circles.) Spread Sauce on each circle.","Sprinkle with Parmesan cheese and oregano. Arrange pepperoni on top and sprinkle with mozzarella cheese.","Bake 20 to 25 minutes or until crust is brown and filling is hot and bubbly."]}],"notes":["From a Gold Medal flour and Red Star yeast recipe card.","Makes 2 pizzas.","*If using self-rising flour, omit salt in the Dough. Unbleached flour can also be used in this recipe."],"images":[{"file":"0124-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"grace-chapel-muffins","title":"Grace Chapel Muffins","from":null,"card":"0144","tags":["muffins","bread","breakfast","blueberry","blueberries","baking","freezer-friendly"],"ingredients":[{"heading":null,"items":["1 1/2 cups all-purpose flour, unsifted","2 teaspoons baking powder","1/2 teaspoon salt","1/2 cup sugar","1 egg, lightly beaten","1/2 cup milk","4 tablespoons butter, melted","1 cup fresh or frozen blueberries"]}],"directions":[{"heading":null,"items":["Preheat oven to 375°. Sift together flour, baking powder, salt and sugar in a mixing bowl.","In a separate bowl, combine egg and milk, then add the melted butter.","Make a well in the center of the dry ingredients and pour in milk mixture, stirring with fork just until dry ingredients are moistened. Fold in blueberries.","Spoon batter into 12 buttered 3-inch muffin tins, filling each tin 2/3 full.","Bake for 20 minutes or until toothpick inserted in center comes out clean. Serve immediately or allow to cool."]}],"notes":["A free recipe from the Grace Chapel Inn kitchen, on a Guideposts \"Tales from Grace Chapel Inn\" book flyer.","Makes 12 muffins.","Muffins may be frozen. To reheat, wrap in foil and place in a preheated 400° oven for 5 minutes."],"images":[{"file":"0144-b.jpg","label":"Front"},{"file":"0144-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"granola-bars","title":"Granola Bars","from":null,"card":"0013","tags":["bars","snack","dessert","oats","raisins","nuts","honey","brown sugar","baking"],"ingredients":[{"heading":null,"items":["3 1/2 cups oats","1 cup raisins","1 cup chopped nuts","2/3 cup butter or oleo","1/2 cup firmly packed brown sugar","1/3 cup honey or molasses","1 egg","1/2 tsp. vanilla","[1/2?] tsp. salt"]}],"directions":[{"heading":null,"items":["Toast oats on a cookie sheet at 350° for 15–20 minutes.","Combine oats with remaining ingredients. Mix well.","Press firmly into a well-greased pan.","Bake at 350° for 20 minutes."]}],"notes":[],"images":[{"file":"0013-b.jpg","label":"Front"},{"file":"0013-a.jpg","label":"Back"}],"sameCard":["holiday-raisin-muffins"]},{"slug":"grape-juice","title":"Grape Juice","from":null,"card":"0136","tags":["drink","juice","grape","grapes","sugar","canning"],"ingredients":[{"heading":null,"items":["Grapes","Water","Sugar (enough for your taste)"]}],"directions":[{"heading":null,"items":["Put water with grapes and enough sugar (for your taste) and cook them.","Run them through a colander, then cheesecloth."]}],"notes":["From Mom: \"For the grape juice - she just puts water with grapes and enough sugar (for your taste) & cooks them.\"","Part of the same note as Pear Preserves (card 0135), which begins \"Mom says\"."],"images":[{"file":"0136-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"green-chili-stew","title":"Green Chili Stew","from":null,"card":"0118","tags":["stew","soup","main dish","pork","green chili","chiles","potatoes","tomatoes","onion","garlic","turkey","leftovers"],"ingredients":[{"heading":null,"items":["3 lbs. pork (cubed) or meat","2 – 8 oz. can stewed tomatoes","2 cups cubed potatoes","1 large chopped onion","2 cloves garlic (minced)","3 cups chopped green chili","Salt to taste"]}],"directions":[{"heading":null,"items":["The card gives no method; it lists the ingredients only."]}],"notes":["Written on \"May His Love Touch Your Day\" notepaper with a kitten and a ball of yarn.","\"2 – 8 oz. can\" means two 8-oz. cans.","If using leftover turkey, add turkey broth."],"images":[{"file":"0118-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"ground-beef-cornbread-casserole","title":"Ground Beef Cornbread Casserole","from":null,"card":"0134","tags":["casserole","main dish","ground beef","hamburger","cornbread","cornbread mix","cream corn","green chilis","onion","cheddar cheese","cheese","mexican"],"ingredients":[{"heading":null,"items":["1 lb ground beef","1 pkg cornbread mix (no sugar)","1 - 17 oz can cream corn","1 egg","1 onion, chopped","1 - 7 oz can chopped green chilis","8 oz. grated cheddar cheese"]}],"directions":[{"heading":null,"items":["Don't prepare cornbread by pkg. directions. Instead combine dry mix with can of corn & egg.","Pour 1/2 batter into buttered casserole dish.","Top with hamburger, add onions, chilis & cheese. Pour rest of batter on top.","Bake @ 350° for [40?]-50 min. till browned."]}],"notes":[],"images":[{"file":"0134-a.jpg","label":"Ingredients"},{"file":"0134-b.jpg","label":"Directions"}],"sameCard":[]},{"slug":"hawaiian-kabobs","title":"Hawaiian Kabobs","from":null,"card":"0113","tags":["kabobs","main dish","grilling","pineapple","green pepper","onion","cherry tomatoes","soy sauce","ginger","marinade","vegetables"],"ingredients":[{"heading":null,"items":["1 can chunk pineapple, 20 oz.","2 large green peppers, cut into 1 in. pieces","1 large onion, quartered","16–18 cherry tomatoes","1/2 cup soy sauce","[1/4?] cup olive oil","1 Tbs. brown sugar","2 tsp. ground ginger","1 tsp. garlic [powder?]","1 tsp. dry mustard","1/4 tsp. pepper"]}],"directions":[{"heading":null,"items":["Drain pineapple, reserving 1/2 cup juice.","Place pineapple chunks & vegetables in a large bowl; set aside.","In a saucepan combine pineapple juice with soy sauce, olive oil, brown sugar & seasonings. Bring to a boil; simmer uncovered for 5 minutes.","Pour over vegetable mixture. Cover & refrigerate for at least 1 hr., stirring occasionally.","Remove pineapple & vegetables from marinade. Grill kabobs for [20?] min. or until soft."]}],"notes":[],"images":[{"file":"0113-b.jpg","label":"Front"},{"file":"0113-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"hersheys-light-chocolate-cake","title":"Hershey's Light Chocolate Cake","from":null,"card":"0148","tags":["cake","dessert","chocolate","cocoa","hershey's","frosting","light","low-fat","skim milk","layer cake","baking"],"ingredients":[{"heading":null,"items":["1 1/4 cups all-purpose flour","1/3 cup Hershey's Cocoa","1 teaspoon baking soda","6 tablespoons extra light corn oil spread","1 cup sugar","1 cup skim milk","1 tablespoon white vinegar","1/2 teaspoon vanilla extract","Light Cocoa Frosting (below)"]},{"heading":"Light Cocoa Frosting","items":["1 envelope (1.3 oz.) dry whipped topping mix","1/2 cup cold skim milk","1 tablespoon Hershey's Cocoa","1/2 teaspoon vanilla extract"]}],"directions":[{"heading":null,"items":["Heat oven to 350°. Spray two 8-inch round baking pans with cooking spray.","Stir flour, cocoa and baking soda; set aside.","In saucepan, melt corn oil spread; stir in sugar. Remove from heat. Add milk, vinegar and vanilla to mixture in saucepan; stir.","Add dry ingredients; whisk until well blended. Pour evenly into pans.","Bake 20 minutes or until wooden pick inserted in center comes out clean. Cool. Frost. Refrigerate."]},{"heading":"Light Cocoa Frosting","items":["In small mixer bowl, stir together whipped topping mix, cold skim milk, cocoa and vanilla extract.","Beat on high speed of mixer about 4 minutes or until soft peaks form."]}],"notes":["From a Hershey's Cocoa label leaflet, \"The Lean Way to Make it Chocolate! 8 Light & Luscious Recipes.\"","12 servings. Per serving: 160 calories, 0 mg cholesterol, 4 g fat."],"images":[{"file":"0148-b.jpg","label":"Front"},{"file":"0148-a.jpg","label":"Back"}],"sameCard":["fruit-filled-chocolate-dreams","chocolate-cupcakes","chocolate-ricotta-cheesecake","creamy-chocolate-and-peach-layered-pudding","silky-cocoa-creme"]},{"slug":"hidden-valley-ranch-dip-and-dressing","title":"Hidden Valley Ranch Dip & Dressing","from":null,"card":"0132","tags":["dip","salad dressing","dressing","ranch","mayonnaise","buttermilk","parsley","onion salt","garlic salt","seasoning mix","homemade mix"],"ingredients":[{"heading":"Dip","items":["2 1/2 T parsley - crushed","1 T onion salt","2 T salt","1/2 t garlic salt","1/2 t black pepper","1/2 T Accent","1 pt mayonnaise"]},{"heading":"Salad Dressing","items":["1 pt. buttermilk"]}],"directions":[{"heading":"Dip","items":["Mix dry ingredients.","Mix 1 pt mayonnaise & dry ingredients."]},{"heading":"Salad Dressing","items":["To make salad dressing, add 1 pt. buttermilk.","Leave uncovered 24 hrs in refrigerator. Put in 2 pt jars."]}],"notes":["\"T\" is tablespoon and \"t\" is teaspoon.","Accent is a seasoning (MSG)."],"images":[{"file":"0132-b.jpg","label":"Front"},{"file":"0132-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"peanut-brittle","title":"[Holder?] Peanut Brittle","from":null,"card":"0018","tags":["candy","dessert","peanuts","corn syrup","sugar","butter"],"ingredients":[{"heading":null,"items":["2 cups raw fresh peanuts","1/2 cup white syrup (light corn syrup)","1 cup sugar","2 tablespoons butter","2 tablespoons hot water","2 teaspoons soda","1 teaspoon vanilla"]}],"directions":[{"heading":null,"items":["Mix all and cook until peanuts pop.","Add soda and vanilla.","Cook until golden brown.","Pour on a buttered cookie sheet. Don't spread, just pour out — this is important!"]}],"notes":[],"images":[{"file":"0018-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"holiday-raisin-muffins","title":"Holiday Raisin Muffins","from":null,"card":"0013","tags":["muffins","bread","breakfast","holiday","raisins","eggnog","baking"],"ingredients":[{"heading":null,"items":["2 cups sifted flour","1/4 cup sugar","1 Tbsp. baking powder","1/2 tsp. salt","1 cup chopped golden raisins","1 cup eggnog","1 egg, slightly beaten","1/4 cup butter, melted"]}],"directions":[{"heading":null,"items":["Sift together dry ingredients. Stir in raisins.","Combine eggnog, egg and butter; add to dry ingredients, mixing lightly.","Fill greased muffin pans 2/3 full.","Bake at 400° for 25 minutes."]}],"notes":[],"images":[{"file":"0013-b.jpg","label":"Front"},{"file":"0013-a.jpg","label":"Back"}],"sameCard":["granola-bars"]},{"slug":"homemade-bread","title":"Homemade Bread","from":null,"card":"0121","tags":["bread","yeast bread","rolls","yeast","flour","shortening","sugar","baking"],"ingredients":[{"heading":null,"items":["2 Tbsp. sugar","2 Tbsp. shortening","1 1/2 tsp. salt","1 cup lukewarm water","1 pkg. cake yeast","3 1/4 cup flour"]}],"directions":[{"heading":null,"items":["Stir in 2 cups [flour?], then add till the right consistency.","Bake [425?] till brown."]}],"notes":["Another version is on card 0120 (Hot Rolls), with the same ingredient list."],"images":[{"file":"0121-a.jpg","label":"Front"},{"file":"0121-b.jpg","label":"Back"}],"sameCard":["pecan-pie-0121"]},{"slug":"hot-rolls","title":"Hot Rolls","from":null,"card":"0120","tags":["rolls","bread","yeast bread","yeast","flour","shortening","sugar","baking"],"ingredients":[{"heading":null,"items":["2 Tbsp. sugar","2 Tbsp. shortening","1 1/2 tsp. salt","1 cup lukewarm water","1 pkg. cake yeast","3 1/4 cups flour"]}],"directions":[{"heading":null,"items":["The card gives no method; it lists the ingredients only."]}],"notes":["Another version, with directions, is on card 0121 (Homemade Bread)."],"images":[{"file":"0120-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"ice-cream","title":"Ice Cream","from":null,"card":"0076","tags":["ice cream","dessert","frozen","homemade ice cream","eggs","evaporated milk","carnation","dream whip","vanilla"],"ingredients":[{"heading":null,"items":["3 tablespoons flour","2 3/4 cups sugar","1 can Carnation","6 eggs","1 Dream Whip","1 tbs Vanilla","Pinch of salt"]}],"directions":[{"heading":null,"items":["Fill to top line of freezer container."]}],"notes":["Makes 1 gallon.","\"Carnation\" is Carnation evaporated milk."],"images":[{"file":"0076-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"impossible-pumpkin-pie","title":"Impossible Pumpkin Pie","from":null,"card":"0109","tags":["pie","dessert","pumpkin","bisquick","evaporated milk","eggs","pumpkin pie spice","thanksgiving","baking","blender"],"ingredients":[{"heading":null,"items":["3/4 cup sugar","1/2 cup Bisquick","2 T. oleo","1 can (13 [oz.?]) evaporated milk","2 eggs","1 can (16 [oz.?]) pumpkin","2 1/2 t. pumpkin pie spice","2 t. vanilla"]}],"directions":[{"heading":null,"items":["Heat oven to 350°. Grease pie pan.","Beat all ingredients until smooth (1 min. in blender).","Pour into plate. Bake 50–55 min. until knife inserted comes out clean."]}],"notes":[],"images":[{"file":"0109-b.jpg","label":"Front"},{"file":"0109-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"jalapeno-cornbread","title":"Jalapeño Cornbread","from":null,"card":"0039","tags":["bread","cornbread","side dish","jalapeño","peppers","cheese","cream-style corn","bacon","pimiento","onion","cornbread mix","baking"],"ingredients":[{"heading":null,"items":["3 cups cornbread mix","2 1/2 cups sweet milk","1/2 cup salad oil","3 eggs, beaten","1 large onion, grated","1 cup canned cream-style corn","1 1/2 cups yellow cheese, grated","1/2 cup jalapeño peppers (roasted, peeled and cooked)","Chopped crisp bacon","Chopped red pepper (canned pimiento may be used)"]}],"directions":[{"heading":null,"items":["Mix well, pour into 13\" x 9\" pan.","Bake in preheated gas oven at 400° F. until done and brown, about 45 minutes."]}],"notes":["Makes 24 two-inch squares."],"images":[{"file":"0039-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"lemon-meringue-pie","title":"Lemon Meringue Pie","from":null,"card":"0033","tags":["pie","dessert","lemon","lemon juice","lemon peel","eggs","cornstarch","pastry shell","meringue"],"ingredients":[{"heading":null,"items":["7 Tbsp. cornstarch","1 1/2 cups sugar","1/2 tsp. salt","2 cups boiling water","3 eggs, separated","1/4 cup lemon juice","2 Tbsp. butter or margarine","1 Tbsp. grated lemon peel","Baked and cooled 9-inch pastry shell"]}],"directions":[{"heading":null,"items":["Combine cornstarch, sugar, and salt. Add the water, and cook until thick, stirring constantly.","Cover and place over boiling water for about 10 minutes, stirring occasionally.","Beat egg yolks slightly, add a little of the hot mixture, stir, and pour back. Cook two minutes, stirring constantly.","Remove from heat and stir in lemon juice, butter or margarine, and grated lemon peel. Pour into pie shell."]}],"notes":["The card itself ends: \"The rest of the recipe was not there.\""],"images":[{"file":"0033-b.jpg","label":"Front"},{"file":"0033-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"lemon-parfait-pie-and-fruit","title":"Lemon Parfait Pie and Fruit","from":null,"card":"0011","tags":["pie","dessert","lemon","gelatin","jello","ice cream","strawberry","raspberry","no-bake"],"ingredients":[{"heading":null,"items":["1 pkg. jello - lemon, straw. or rasp.","1 1/4 cup hot water","3 Tbsp. lemon juice","Rind one lemon","1 pt. vanilla ice cream"]}],"directions":[{"heading":null,"items":["Dissolve jello in hot water.","Add lemon juice, rind and ice cream.","Let thicken then pour into shell."]}],"notes":[],"images":[{"file":"0011-b.jpg","label":"Front"},{"file":"0011-a.jpg","label":"Back"}],"sameCard":["fresh-fruit-pie","canned-fruit-pie"]},{"slug":"lemon-roll","title":"Lemon Roll","from":null,"card":"0044","tags":["cake","jelly roll","cake roll","dessert","lemon","lemon juice","lemon rind","lemon extract","eggs","butter","make-ahead","baking"],"ingredients":[{"heading":"Filling","items":["6 Tbsp. lemon juice","1 1/2 cups sugar","1 1/2 sticks butter or margarine","Grated rind of 2 lemons","3 eggs, well beaten"]},{"heading":"Roll","items":["4 eggs, at room temperature","1/8 tsp. salt","1 tsp. baking powder","3/4 cup sugar","3/4 cup sifted cake flour","1/2 tsp. lemon extract","Powdered sugar, for dusting"]}],"directions":[{"heading":"Filling","items":["Combine lemon juice, sugar, butter and lemon rind in top of double boiler and stir over hot water until blended.","Add eggs and stir continuously until thick, about 15 minutes.","Refrigerate at least 4 hrs."]},{"heading":"Roll","items":["Grease, line with wax paper and grease again a 10\" by 15\" baking sheet.","Beat eggs, salt and baking powder until fluffy. Add sugar very slowly, beating continuously, until very thick.","Fold in lemon extract, then flour. Pour in prepared pan.","Bake at 375° for 13–15 min.","Invert roll on wax paper heavily dusted with powdered sugar. Pull away baked paper. Cool slightly.","Spread with lemon filling and form into a roll. For a tight, neat roll use only part of the filling and save the rest for little tarts or to spread on pound cake. For a rich, cozy one, use it all."]}],"notes":["From the card: the filling \"turns a simple jelly roll into a rich and elegant dessert,\" and it keeps well \"(provided you hide it),\" so it can be made the day before.","With the full filling, it serves 8 or 10 easily."],"images":[{"file":"0044-b.jpg","label":"Front"},{"file":"0044-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"lemon-supreme-cake-mix","title":"Lemon Supreme Cake Mix","from":null,"card":"0047","tags":["cake","dessert","lemon","cake mix","pudding","jello","eggs","glaze","powdered sugar","baking"],"ingredients":[{"heading":null,"items":["4 eggs","Lemon Jello pudding","1/4 cup Crisco oil","2/3 cup water","1 tsp. lemon extract"]},{"heading":"Topping","items":["1 lemon juice","2 tab butter","1 1/2 cups powdered sugar"]}],"directions":[{"heading":null,"items":["Mix together."]},{"heading":"Topping","items":["Melt, add lemon juice, sugar. Punch holes. Spoon in glaze."]}],"notes":["\"1 lemon juice\" means the juice of 1 lemon."],"images":[{"file":"0047-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"lima-bean-casserole","title":"Lima Bean Casserole","from":null,"card":"0110","tags":["casserole","side dish","lima beans","beans","mushrooms","cream of celery soup","pimiento","parmesan","cheese","cream","crock-pot","slow cooker"],"ingredients":[{"heading":null,"items":["2 small onions, thinly sliced","3 pkg. (10 oz. each) frozen baby lima beans, thawed","2 cans (10 3/4 oz. each) condensed cream of celery soup","2 cans (4 oz. each) sliced mushrooms, undrained","1 jar (2 oz.) chopped pimiento, drained","1/8 t. pepper","1/2 t. dill seed","1/2 cup heavy cream","1 cup grated Parmesan cheese"]}],"directions":[{"heading":null,"items":["Combine all ingredients except heavy cream and Parmesan cheese in Crock-Pot; stir well.","Cover and cook on low setting for 10 to 12 hours. Or low 5 hours.","Just before serving, add cream and stir well; sprinkle Parmesan cheese on top."]}],"notes":["Makes 8 to 10 servings (about 3 qts.)."],"images":[{"file":"0110-b.jpg","label":"Front"},{"file":"0110-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"lime-fluff","title":"Lime Fluff","from":null,"card":"0048","tags":["dessert","gelatin","jello","lime","pineapple","dream whip","whipped topping","vanilla wafers","chilled"],"ingredients":[{"heading":null,"items":["1/2 cup cold milk","1/2 tsp. vanilla","1 envelope Dream Whip","1 pkg Lime Jell-O","2 Tbsp. sugar","1/2 tsp. salt","1 cup hot water","Pineapple juice and water to make 1 cup","2/3 cup drained canned crushed pineapple","1 box small vanilla wafers"]}],"directions":[{"heading":null,"items":["Combine milk, vanilla, and Dream Whip; whip as directed on package. Chill.","Dissolve the Jell-O, sugar, and salt in hot water. Add juice and water and chill until slightly thickened.","Place in bowl of ice and water; beat until fluffy and thick.","Fold in Dream Whip and pineapple.","Pour into dessert dishes lined with wafers. Chill until firm."]}],"notes":["Serves 8 to 10."],"images":[{"file":"0048-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"lollipops","title":"Lollipops","from":null,"card":"0023","tags":["candy","lollipops","hard candy","sugar","karo","corn syrup","kids"],"ingredients":[{"heading":null,"items":["3 cups of sugar","1 cup of Karo","2 cups of water","Flavoring","Coloring"]}],"directions":[{"heading":null,"items":["Boiled together until a drop becomes brittle when dropped in water.","Pour drops on table and stick lollipop sticks in them."]}],"notes":[],"images":[{"file":"0023-a.jpg","label":"Front"},{"file":"0023-b.jpg","label":"Back"}],"sameCard":[]},{"slug":"magic-topping","title":"Magic Topping","from":null,"card":"0027","tags":["topping","cake","dessert","coconut","brown sugar","shortening","broiled topping","baking"],"ingredients":[{"heading":null,"items":["3/4 cup coconut","3/4 cup light brown sugar","1/2 tsp. salt","1/3 cup shortening","2 Tbsp. milk"]}],"directions":[{"heading":null,"items":["Combine ingredients and cook, stirring constantly, until sugar melts.","Spread on top of warm cake. Return to 375° oven for 10–12 min. until lightly browned."]}],"notes":[],"images":[{"file":"0027-b.jpg","label":"Front"},{"file":"0027-a.jpg","label":"Back"}],"sameCard":["creamy-honey-frosting","butterscotch-sauce"]},{"slug":"meat-loaf","title":"Meat Loaf","from":null,"card":"0025","tags":["main dish","meat loaf","beef","ground beef","oats","onion","tomato juice","baking"],"ingredients":[{"heading":null,"items":["1 1/2 lbs. ground beef","3/4 cup oats","2 eggs","1/4 cup chopped onions","2 tsp. salt","1/4 tsp. pepper","1 cup tomato juice"]}],"directions":[{"heading":null,"items":["Bake at 350° for 1 hour."]}],"notes":[],"images":[{"file":"0025-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"mexican-chili-burgers","title":"Mexican Chili Burgers","from":null,"card":"0147","tags":["main dish","sandwich","burgers","ground beef","beef","cheese","velveeta","green chilies","salsa","mexican","kraft"],"ingredients":[{"heading":null,"items":["1 pound ground beef","1 medium (1/2 cup) onion, chopped","1 can (4 ounces) chopped green chilies, drained","1 tablespoon red pepper sauce","1 egg, beaten","1/4 cup dry bread crumbs","6 hamburger buns","Lettuce leaves","6 Velveeta Slices Process Cheese Spread","Salsa"]}],"directions":[{"heading":null,"items":["Combine first six ingredients. Form into 6 patties.","Broil 5 minutes on each side or until desired doneness.","Top with process cheese spread; continue broiling until melted.","For each sandwich, layer lettuce, cooked cheeseburger and salsa on hamburger bun."]}],"notes":["From a Kraft Velveeta recipe leaflet.","Makes 6 servings. Prep time: 15 minutes. Cooking time: 12 minutes."],"images":[{"file":"0147-b.jpg","label":"Front"},{"file":"0147-a.jpg","label":"Back"}],"sameCard":["cheesy-chicken-enchiladas","shells-and-cheese-florentine","chicken-fajita-pizzas","tex-mex-fondue"]},{"slug":"mitchel-corn-bread","title":"Mitchel Corn Bread","from":null,"card":"0092","tags":["cornbread","bread","main dish","casserole","corn","creamed corn","hamburger","chicken","turkey","onion","cheese","jalapeño","chili","freezer","baking"],"ingredients":[{"heading":null,"items":["1 can creamed corn","1 chopped onion","1 pk. shredded cheese","Jalapeño or chili for flavor","Meat: browned hamburger, or chopped & cooked chicken, or chopped & cooked turkey"]}],"directions":[{"heading":null,"items":["Cook 40-50 minutes @ 350°."]}],"notes":["Written beside the title: \"no eggs for freezing.\"","A variation of the Vicki Maize Cornbread recipe on the other side of this card."],"images":[{"file":"0092-b.jpg","label":"Front"},{"file":"0092-a.jpg","label":"Back"}],"sameCard":["vicki-maize-cornbread"]},{"slug":"molasses-crinkles","title":"Molasses Crinkles","from":null,"card":"0067","tags":["cookies","dessert","molasses","shortening","cinnamon","ginger","cloves","raisins","spice","baking"],"ingredients":[{"heading":null,"items":["3/4 cup shortening","1 cup sugar","1 egg","1/4 cup molasses","2 1/4 cup flour","2 tsp. soda","1/4 tsp. salt","1/2 tsp. cloves","1 tsp. cinnamon","1 tsp ginger","[1?] to 1/2 cup raisins (if desired)","Sugar, for dipping"]}],"directions":[{"heading":null,"items":["Mix thoroughly shortening, sugar, egg and molasses.","Sift together flour, soda, salt, cloves, cinnamon and ginger, and stir in.","Add [1?] to 1/2 cup raisins if desired.","Roll into balls the size of walnuts. Dip tops in sugar; place sugared side up on greased baking sheet.","Bake just until set but not hard. Baking 375 10 to 12 minutes."]}],"notes":[],"images":[{"file":"0067-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"moms-applesauce-cake","title":"Mom's Applesauce Cake","from":null,"card":"0114","tags":["cake","dessert","applesauce","apple","raisins","nuts","cocoa","spice cake","cinnamon","cloves","bundt","baking"],"ingredients":[{"heading":null,"items":["2 cups sugar","3 cups stewed apples","4 cups flour","1 cup raisins","1 T. cocoa powder","1/4 tsp. salt","1 cup nuts (broken)","1 cup butter","1 tsp. cinnamon","1 tsp. allspice","1 tsp. cloves","Sprinkle of nutmeg","4 tsp. soda"]}],"directions":[{"heading":null,"items":["Cream apples, butter & sugar in large bowl. Add spices & salt.","Stir in raisins & nuts. Cocoa.","Add flour 1 cup at a time. Add soda last.","Bake in large Bundt pan until toothpick comes out clean, about an hour in 350° oven."]}],"notes":[],"images":[{"file":"0114-b.jpg","label":"Front"},{"file":"0114-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"nachos","title":"Nachos","from":null,"card":"0080","tags":["appetizer","snack","mexican","nachos","tortilla chips","corn tortillas","cheese","velveeta","cheese dip","quick"],"ingredients":[{"heading":null,"items":["Corn tortillas","Oil (about 1 cup)","Salt","Velveeta cheese","1/3 cup milk"]}],"directions":[{"heading":null,"items":["Cut corn tortillas up in triangles.","Put oil in pan - about 1 cup. Heat. Brown. Salt to taste.","Melt Velveeta cheese w/ 1/3 cup milk over low heat. Pour or dip w/ chips. (nacho)"]}],"notes":["The card calls it \"(easy, quick.)\""],"images":[{"file":"0080-b.jpg","label":"Front"},{"file":"0080-a.jpg","label":"Back"}],"sameCard":["salsa"]},{"slug":"no-cook-magic-lemon-meringue-pie","title":"No Cook Magic Lemon Meringue Pie","from":null,"card":"0055","tags":["pie","dessert","lemon","meringue","sweetened condensed milk","eagle brand","corn flake crumbs","kellogg's","egg whites","no-cook"],"ingredients":[{"heading":"Crust","items":["3/4 cup Kellogg's Corn Flake Crumbs","2 Tbsp. sugar","1/4 cup butter or margarine, melted"]},{"heading":"Filling","items":["1 can Borden's Eagle Brand Sweetened Condensed Milk","1/2 cup lemon juice or bottled lemon juice","1 tsp. grated lemon peel","2 egg yolks"]},{"heading":"Meringue","items":["2 egg whites","1/4 tsp. cream of tartar","1/4 cup sugar"]}],"directions":[{"heading":"Crust","items":["In an 8-inch pie pan, blend together crumbs, sugar, and melted butter.","Press firmly and evenly onto bottom and sides of pan. Chill."]},{"heading":"Filling","items":["In a mixing bowl, blend milk, lemon juice, peel and yolks until thoroughly blended.","Fill crumb crust."]},{"heading":"Meringue","items":["In a small bowl whip whites with cream of tartar until they hold a soft peak.","Gradually whip in sugar; continue to whip just until whites hold firm peaks.","Pile onto pie filling and seal to inside edge of pie shell.","Bake in 325° (slow) oven until golden brown, about 15 minutes. Cool."]}],"notes":["Uses Kellogg's and Borden's Eagle Brand products.","Makes an 8-inch pie."],"images":[{"file":"0055-a.jpg","label":"Front"},{"file":"0055-b.jpg","label":"Back"}],"sameCard":[]},{"slug":"no-bake-chocolate-cherry-mini-tarts","title":"No-Bake Chocolate Cherry Mini-Tarts","from":null,"card":"0116","tags":["tarts","dessert","no-bake","chocolate","cocoa","cherry","candied cherries","almonds","vanilla wafers","cream cheese","hershey's","christmas"],"ingredients":[{"heading":null,"items":["2 cups confectioners' sugar","1 cup vanilla wafer crumbs (about 30 cookies)","1 cup ground blanched almonds","1/2 cup Hershey's Cocoa","1/3 cup milk","Cherry Tart Filling (below)","Candied cherries, quartered, optional"]},{"heading":"Cherry Tart Filling","items":["1 package (3 ounces) cream cheese, softened","2 cups confectioners' sugar","1 teaspoon vanilla extract","1/4 teaspoon almond extract","1/2 cup coarsely chopped blanched almonds","1/4 cup candied cherries, quartered"]}],"directions":[{"heading":null,"items":["Paper-line 30 miniature muffin cups (1 3/4 inches in diameter); set aside.","In a large bowl combine confectioners' sugar, wafer crumbs, almonds and cocoa. Sprinkle in milk, mixing until ingredients are moistened and cling together.","Shape into walnut-size pieces; place in prepared cups. Press mixture against bottom and side of each cup to form shell. Chill.","Spoon Cherry Tart Filling into shells. Garnish with candied cherry quarters, if desired. Chill until firm."]},{"heading":"Cherry Tart Filling","items":["Beat cream cheese in small bowl. Gradually add confectioners' sugar, vanilla and almond extract, beating until smooth.","Stir in almonds and cherries."]}],"notes":["From an Ideals magazine flyer offering a free Hershey's Chocolate Cookbook.","Makes about 30 tarts."],"images":[{"file":"0116-b.jpg","label":"Flyer"},{"file":"0116-a.jpg","label":"Flyer back"}],"sameCard":[]},{"slug":"old-fashioned-bran-muffins","title":"Old-Fashioned Bran Muffins","from":null,"card":"0005","tags":["muffins","bread","breakfast","bran","all-bran cereal","milk","baking"],"ingredients":[{"heading":null,"items":["1 cup all bran","3/4 cup milk","1 egg","1/4 cup soft shortening","1 cup sifted flour","2 1/2 teaspoons baking powder","1/2 tsp. salt","1/4 cup sugar"]}],"directions":[{"heading":null,"items":["400° for 30 minutes."]}],"notes":["\"All bran\" is All-Bran cereal."],"images":[{"file":"0005-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"onion-rings-0142","title":"Onion Rings","from":null,"card":"0142","tags":["side dish","appetizer","onion rings","onion","batter","fried","flour","egg","milk"],"ingredients":[{"heading":null,"items":["1 c. flour","1/2 tsp. salt","1 egg, beaten","1 c. milk","2 tbsp oil"]}],"directions":[{"heading":null,"items":["No directions on the card."]}],"notes":["Another Onion Rings batter, made with buttermilk, is on card 0143."],"images":[{"file":"0142-b.jpg","label":"Front"},{"file":"0142-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"onion-rings-0143","title":"Onion Rings","from":null,"card":"0143","tags":["side dish","appetizer","onion rings","onion","batter","fried","buttermilk","flour","egg"],"ingredients":[{"heading":null,"items":["1 egg","1 c. buttermilk","1 1/3 c. flour","1/2 tsp. salt","1/2 tsp. baking soda","Shortening, for cooking"]}],"directions":[{"heading":null,"items":["Beat egg & buttermilk together.","Dip.","Cook in hot shortening."]}],"notes":["Another Onion Rings batter, made with milk and oil, is on card 0142."],"images":[{"file":"0143-b.jpg","label":"Front"},{"file":"0143-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"orange-sauce","title":"Orange Sauce","from":null,"card":"0030","tags":["sauce","dessert sauce","orange","orange juice","orange rind","sugar","cornstarch","butter"],"ingredients":[{"heading":null,"items":["1 cup sugar","1/4 tsp. salt","2 tsp. cornstarch","1 cup orange juice","1 cup boiling water","1 Tbsp. butter","2 tsp. grated orange rind"]}],"directions":[{"heading":null,"items":["Mix in saucepan sugar, salt, and cornstarch.","Stir in orange juice and boiling water.","Boil 1 min., stirring constantly.","Remove from heat, add butter and grated orange rind."]}],"notes":["The card describes it as a \"clear orange sauce.\""],"images":[{"file":"0030-b.jpg","label":"Front"},{"file":"0030-a.jpg","label":"Back"}],"sameCard":["fudge"]},{"slug":"paper-bag-apple-pie","title":"Paper Bag Apple Pie","from":null,"card":"0126","tags":["pie","dessert","apple","cinnamon","brown sugar","butter","crumb topping","baking"],"ingredients":[{"heading":"Filling","items":["1 unbaked nine-inch piecrust (homemade or ready-made)","6-7 cups (about six apples) tart apples, peeled, cored and cut into thick slices","1/2 cup granulated sugar","1/2 teaspoon cinnamon","2 tablespoons flour","2 tablespoons lemon juice"]},{"heading":"Topping","items":["1/2 cup brown sugar","1/2 cup flour","1/2 cup butter"]}],"directions":[{"heading":"Filling","items":["Place unbaked crust in pie pan. Prepare apples and put in bowl.","In a separate bowl, combine sugar, cinnamon and flour. Gently combine flour mixture with apples, and spoon into piecrust. Sprinkle with lemon juice."]},{"heading":"Topping","items":["Combine brown sugar and flour, and then cut in the butter to create a coarse mixture (about the size of peas). Sprinkle mixture evenly over the top of the apples.","Slide pie into a brown paper bag (like a grocery store bag), and fold the open end over twice and secure with large metal paper clips.","Bake on a cookie sheet at 425° for one hour. Carefully split open the bag and allow pie to cool on wire rack."]}],"notes":["Tip from the clipping: cooking inside the paper bag helps the apples heat thoroughly without overbaking the crust."],"images":[{"file":"0126-b.jpg","label":"Clipping"},{"file":"0126-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"party-cheese-dip","title":"Party Cheese Dip","from":null,"card":"0022","tags":["dip","appetizer","party","cheese","cottage cheese","cream cheese","sour cream","smoked oysters","oysters","make-ahead"],"ingredients":[{"heading":null,"items":["2 cups (16 oz.) cottage cheese","3 oz. cream cheese","1/4 cup sour cream","1 Tbsp. grated onion","1 tsp. seasoning salt","Few drops hot pepper sauce","1 tsp. soy sauce","1 can (3 2/3 oz) or (1/2 cup) smoked oysters, drained and chopped"]}],"directions":[{"heading":null,"items":["Beat together cottage cheese, cream cheese and sour cream until well blended.","Add onion, seasoning salt, hot pepper sauce, soy sauce and oysters; beat well.","Chill for several hours."]}],"notes":["Makes about 3 1/4 cups."],"images":[{"file":"0022-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"peanut-butter-bars","title":"Peanut Butter Bars","from":null,"card":"0064","tags":["bars","cookies","dessert","peanut butter","brown sugar","butter","baking"],"ingredients":[{"heading":null,"items":["1/2 cup butter","1/2 cup peanut butter","1 1/2 tsp. vanilla extract","1/2 cup sugar","1/2 cup firmly packed brown sugar","1 egg","1 1/4 cups flour","2 tsp. baking powder","1/4 tsp. salt"]}],"directions":[{"heading":null,"items":["Cream butter, peanut butter, and extract thoroughly; add the sugars gradually, creaming until fluffy. Add egg and beat thoroughly.","Blend the remaining ingredients; add in thirds to creamed mixture, mixing until blended.","Press into a 15 1/2 x 10 1/2 x 1 inch pan.","Bake at 375° for 15 to 20 minutes.","While warm, cut into bars or, if desired, into diamond shapes."]}],"notes":["Makes about 4 1/2 dozen cookies."],"images":[{"file":"0064-b.jpg","label":"Front"},{"file":"0064-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"pear-preserves","title":"Pear Preserves","from":null,"card":"0135","tags":["preserves","jam","canning","pear","pears","fruit","sugar"],"ingredients":[{"heading":null,"items":["Pears","Sugar","Water"]}],"directions":[{"heading":null,"items":["Peel and cut pears up.","Soak them overnight in heavy sugar water (meaning quite a bit of sugar, like jelly).","Then cook them on low heat until thickened syrup consistency."]}],"notes":["Written on the card as Mom's own words: \"Mom says 'I peel & cut pears up…'\""],"images":[{"file":"0135-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"pecan-pie-0121","title":"Pecan Pie","from":null,"card":"0121","tags":["pie","dessert","pecans","nuts","brown sugar","karo","corn syrup","eggs","lemon"],"ingredients":[{"heading":null,"items":["3 [oz.?] … cut up","1 tbs. lemon juice","3 eggs","[2/3?] cup brn. sugar","1/2 cup Karo","2 tsp. vanilla","Pecans, whole","Pie crust"]}],"directions":[{"heading":null,"items":["The card gives no method; it lists the ingredients only."]}],"notes":["A different pecan pie recipe is on card 0122."],"images":[{"file":"0121-a.jpg","label":"Front"},{"file":"0121-b.jpg","label":"Back"}],"sameCard":["homemade-bread"]},{"slug":"pecan-pie-0122","title":"Pecan Pie","from":null,"card":"0122","tags":["pie","dessert","pecans","nuts","karo","corn syrup","sugar","eggs","vanilla","baking"],"ingredients":[{"heading":null,"items":["3 eggs","1 cup Karo syrup","1 cup sugar","1 cup pecan halves","1 tsp. vanilla","1 unbaked pie shell","Salt"]}],"directions":[{"heading":null,"items":["Beat eggs & sugar until thick.","Add vanilla, Karo & salt. Mix; pour over nuts in shell.","Bake at 300° for 50 to 60 min."]}],"notes":["Written on the back of a menu flyer for Broasty Jr. restaurant in Clovis (\"Next to Thunderbird Drive-In\")","A different pecan pie recipe is on card 0121."],"images":[{"file":"0122-b.jpg","label":"Front"},{"file":"0122-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"penuche","title":"Penuche","from":null,"card":"0071","tags":["candy","fudge","dessert","brown sugar","cream","nuts"],"ingredients":[{"heading":null,"items":["1 1/2 c. sugar","1 c. brown sugar","1/3 c. light cream","1/3 c. milk","2 Tbsp. butter","1 tsp. vanilla","1/2 c. broken nuts"]}],"directions":[{"heading":null,"items":["Butter the sides of a heavy 2-qt. saucepan. In it combine sugars, cream, milk and butter.","Heat over medium heat, stirring constantly, till sugars dissolve and mixture comes to boiling.","Cook to soft ball stage (238°), stirring only if necessary.","Immediately remove from heat and cool to lukewarm (110°). Do not stir.","Add vanilla. Beat vigorously till candy becomes very thick and starts to lose its gloss.","Quickly stir in nuts and spread in a buttered shallow pan. Score while warm; cut when firm."]}],"notes":["Dated 2008. Ends with \"Enjoy\" and a little heart."],"images":[{"file":"0071-b.jpg","label":"Front"},{"file":"0071-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"perfect-sugar-cookies","title":"Perfect Sugar Cookies","from":null,"card":"0078","tags":["cookies","sugar cookies","dessert","butter","margarine","sour cream","vanilla","baking"],"ingredients":[{"heading":null,"items":["1 cup butter or mar","1 tsp vanilla","1 1/2 cup sugar","2 beaten eggs","1/2 teaspoon soda","3 tbs thick sour cream","3 cups sifted flour","1/4 teaspoon salt"]}],"directions":[{"heading":null,"items":["Cream butter w. sugar.","Dissolve soda in sour cream.","Bake @ 400° 5 min or until golden brown."]}],"notes":["\"Mar\" is short for margarine."],"images":[{"file":"0078-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"pineapple-upside-down-cake","title":"Pineapple Upside-Down Cake","from":null,"card":"0059","tags":["cake","dessert","pineapple","upside-down cake","brown sugar","maraschino cherries","nuts","c and h sugar","whipped cream","baking"],"ingredients":[{"heading":"Topping","items":["3 Tbsp. butter or margarine","1 cup C and H Light Brown Sugar*","Pineapple slices (or chunks, tidbits, or crushed, slightly drained)","Nuts","Maraschino cherries"]},{"heading":"Cake Batter","items":["3 eggs, separated","1 cup C and H Granulated Sugar*","1/4 tsp. salt","1/2 cup hot pineapple syrup","1 cup cake flour","1 tsp. baking powder"]},{"heading":"To Serve","items":["Whipped cream"]}],"directions":[{"heading":"Topping","items":["Melt 3 Tbsp. butter or margarine in a 9\" square cake pan. Sprinkle 1 cup C and H Light Brown Sugar over bottom.","Arrange pineapple slices (or chunks, tidbits, or crushed, slightly drained) with nuts and Maraschino cherries over sugar to make a pretty design.","Put into oven to warm while you mix the cake batter."]},{"heading":"Cake Batter","items":["Beat egg yolks until light. Gradually beat in sugar, salt and hot pineapple syrup.","Stir in flour sifted with baking powder. Fold in stiffly beaten egg whites.","Pour over fruit mixture. Bake at 350° (moderate) 35 to 45 minutes, or until done.","Turn out. Top with whipped cream."]}],"notes":["A C and H Sugar recipe. The sugars are starred, with the footnote \"*.....pure CANE, of course.\"","Makes 6 to 9 servings."],"images":[{"file":"0059-a.jpg","label":"Front"},{"file":"0059-b.jpg","label":"Back"}],"sameCard":[]},{"slug":"pineapple-upside-down-gingerbread","title":"Pineapple Upside-Down Gingerbread","from":null,"card":"0068","tags":["cake","dessert","gingerbread","pineapple","upside-down cake","cherries","pecans","brown sugar","cake mix","betty crocker","del monte","baking"],"ingredients":[{"heading":null,"items":["1/4 cup butter","1/2 cup brown sugar (packed)","1/3 cup candied cherry halves or pecan halves","6 drained Del Monte Pineapple Slices","1 pkg. Betty Crocker Gingerbread Mix"]}],"directions":[{"heading":null,"items":["Heat oven to 350°.","Melt butter in 9\" round or 9\" sq. pan. Blend in sugar. Spread in pan; sprinkle with cherry or pecan halves. Arrange pineapple slices over bottom of pan.","Make batter as directed on Betty Crocker package. Pour into prepared pan.","Bake 40 to 45 minutes. Let cake stand a few minutes before inverting on plate. Serve warm."]}],"notes":[],"images":[{"file":"0068-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"pinto-beans","title":"Pinto Beans","from":null,"card":"0102","tags":["beans","pinto beans","side dish","soaking","slow cooking"],"ingredients":[{"heading":null,"items":["1 cup beans","3 cups water (for soaking)","3-4 cups water (for cooking)"]}],"directions":[{"heading":"Quick Soak","items":["Bring 1 cup beans and 3 cups water to boil for 2 minutes.","Remove from heat. Cover & let stand 1 hour.","Drain soak water & rinse beans."]},{"heading":"Overnight Soak","items":["Same amount beans & water (cold). Let it stand overnight or 8 hours.","Drain & rinse beans."]},{"heading":"Cooking","items":["Add 3-4 cups water to rinsed and rinsed, simmer gently with lid tilted until desired tenderness is reached, 1 1/2 - 2 hours."]}],"notes":["Written at the top: \"Can double, triple, whatever.\""],"images":[{"file":"0102-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"pizza-dough","title":"Pizza Dough","from":"Betty [Workman?] / Viki Love","card":"0088","tags":["pizza","bread","dough","main dish","yeast","flour","spaghetti sauce","mozzarella","cheese","baking"],"ingredients":[{"heading":null,"items":["1 pkg. dry yeast (1 TB)","1 cup warm water","1 tsp. sugar","1 tsp. salt","2 TB salad oil","2 1/2 c. flour"]}],"directions":[{"heading":null,"items":["Dissolve yeast in warm water. Stir in remaining dough ingredients.","Beat vigorously about 20 strokes.","Allow dough to rest about 5-10 min.","Top with spaghetti sauce & mozzarella cheese.","Bake 450° - 12 min."]}],"notes":["From the kitchen of Betty [Workman?] / Viki Love, '87.","Makes two 12-inch pizza crusts.","Written on a \"Here's what's cooking\" card with a cornucopia and the verse Joel 2:26."],"images":[{"file":"0088-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"pizza-sauce","title":"Pizza Sauce","from":null,"card":"0014","tags":["sauce","pizza","tomato puree","romano cheese","cheese","oregano","olive oil","garlic"],"ingredients":[{"heading":null,"items":["Tomato puree","Vegetable oil","Imported Romano Cheese","Salt","Oregano","Olive oil","Black pepper","Garlic"]}],"directions":[{"heading":null,"items":["The card gives no directions."]}],"notes":[],"images":[{"file":"0014-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"popcorn-balls-0104","title":"Popcorn Balls","from":null,"card":"0104","tags":["candy","snack","popcorn","popcorn balls","corn syrup","sugar"],"ingredients":[{"heading":null,"items":["1/2 c. wh. syrup","1/2 c. wh. sugar","1/2 tsp. salt","Popcorn (about 3 1/2 small batches)"]}],"directions":[{"heading":null,"items":["Mix ingred. in kettle; boil for 1 min.","Pour over popcorn. Form into balls."]}],"notes":["\"Wh.\" means white: white syrup is light corn syrup, and white sugar is granulated sugar."],"images":[{"file":"0104-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"popcorn-balls","title":"Popcorn Balls","from":null,"card":"0034","tags":["candy","popcorn balls","snack","popcorn","corn syrup","honey","sugar","butter","halloween"],"ingredients":[{"heading":"No. 1","items":["3 quarts popped corn","1 cup sugar","1/3 cup white corn syrup","1 cup water","1/4 tsp. salt","1 tsp. lemon or vanilla"]},{"heading":"No. 2","items":["3 quarts popped corn","1 cup honey","1 cup sugar","2/3 cup water","2 Tbsp. butter","1/4 tsp. salt"]}],"directions":[{"heading":"No. 1","items":["Place the popped corn into a large pan.","Cook sugar, syrup and water to 280° F. Add flavoring and salt.","Pour over the corn, stirring with a spoon so that all kernels will be evenly coated.","Shape the corn into balls, lay on waxed paper to harden."]},{"heading":"No. 2","items":["Proceed as for No. 1."]}],"notes":[],"images":[{"file":"0034-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"potato-latkes","title":"Potato Latkes","from":null,"card":"0149","tags":["side dish","potato pancakes","latkes","potatoes","onion","eggs","flour","fried","hanukkah","jewish"],"ingredients":[{"heading":null,"items":["2 large white potatoes","1/2 onion","2 eggs","1/4 cup flour","1 teaspoon salt","Oil for frying"]}],"directions":[{"heading":null,"items":["Wash, scrub and cut potatoes into proper size for food processor or blender. Do not peel!","Add all ingredients to processor or blender, then use on/off control until blended but not chopped too fine.","Pour mixture into bowl.","Heat oil in skillet.","Drop mixture by tablespoons into hot skillet and fry on both sides until brown.","Serve plain or with applesauce or sour cream."]}],"notes":["From a newspaper Hanukkah feature: \"Here's the recipe for the Brachman's latkes.\"","Nutrition per latke: 156 calories, 11 grams fat, 27 milligrams cholesterol, 159 milligrams sodium, 64 percent of calories from fat."],"images":[{"file":"0149-b.jpg","label":"Clipping"},{"file":"0149-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"prickly-pear-jelly-0084","title":"Prickly Pear Jelly","from":null,"card":"0084","tags":["jelly","preserves","canning","prickly pear","cactus","lemon","sure-jell","pectin","southwestern"],"ingredients":[{"heading":null,"items":["4 1/2 cups juice","1/2 cup lemon juice","1 box Sure-Jell","6 1/2 cups of sugar"]}],"directions":[{"heading":null,"items":["Combine juice, Sure-Jell, lemon juice. Bring to a fast boil.","Add sugar when it comes to a fast boil that cannot be stirred down.","Then boil [2?] minutes. [Transfer?], skim & pour up.","Seal with lids or paraffin."]}],"notes":["Another version is on card 0107."],"images":[{"file":"0084-b.jpg","label":"Front"},{"file":"0084-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"prickly-pear-jelly","title":"Prickly Pear Jelly","from":null,"card":"0107","tags":["jelly","preserves","canning","prickly pear","cactus","lemon","pectin","sure-jell","sugar"],"ingredients":[{"heading":null,"items":["4 1/2 cups of juice","1/2 cup lemon juice","1 box Sure-Jell","[6?] 1/2 cups of sugar"]}],"directions":[{"heading":null,"items":["Combine juice, Sure-Jell, lemon juice. Bring to a fast boil.","Add sugar. When it comes to a fast boil that cannot be stirred down, boil 2 minutes.","Remove from fire, skim, pour up. Seal with lids or paraffin."]}],"notes":["Another version is on card 0084."],"images":[{"file":"0107-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"quiche","title":"Quiche","from":null,"card":"0100","tags":["quiche","main dish","breakfast","eggs","bacon","cheese","cream","pie crust"],"ingredients":[{"heading":null,"items":["9\" pie crust (frozen)","4 large eggs","1 1/4 cup heavy cream","1 3/4 cup cheese, or Gruyère ([2 ounces?])","4–5 slices cooked bacon, crisp","Salt / pepper","[1/4?] tsp. thyme"]}],"directions":[{"heading":null,"items":["Cook approx. [30?] min. @ 350° till firm."]}],"notes":[],"images":[{"file":"0100-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"quick-cobbler","title":"Quick Cobbler","from":null,"card":"0119","tags":["cobbler","dessert","fruit","apples","blueberries","butter","flour","milk","baking powder","baking","quick"],"ingredients":[{"heading":null,"items":["1 stick of butter","3 cups sweetened fruit (apples, blueberries, whatever)","1 cup flour","2 ts. baking powder","1 ts. salt","1 cup milk"]}],"directions":[{"heading":null,"items":["Melt stick of butter in cobbler pan.","Add 3 cups sweetened fruit.","Mix flour, baking powder, salt & milk. Pour over fruit.","Cook at 400° till golden. Delicious!"]}],"notes":["Shared at the end of a family letter to \"Mommie & Daddy,\" which calls it \"a delicious QUICK recipe for a cobbler.\""],"images":[{"file":"0119-b.jpg","label":"Letter, page 1"},{"file":"0119-a.jpg","label":"Letter, page 2"}],"sameCard":[]},{"slug":"red-velvet-cake","title":"Red Velvet Cake","from":null,"card":"0042","tags":["cake","red velvet","dessert","buttermilk","cocoa","chocolate","crisco","shortening","food coloring","icing","frosting","baking"],"ingredients":[{"heading":null,"items":["1/2 cup Crisco","1 1/2 cups sugar","1 tsp. salt","2 eggs","2 cups flour","1 Tbsp. vinegar","1 tsp. vanilla","2 oz. red cake coloring","1 Tbsp. cocoa","1 cup buttermilk","1 tsp. soda","Icing (below)"]},{"heading":"Icing","items":["1 cup milk","Pinch of salt","1 cup Crisco","1/4 cup flour","1 cup sugar","2 tsp. vanilla"]}],"directions":[{"heading":null,"items":["Combine shortening and sugar, add coloring, eggs, vanilla.","Sift flour, cocoa and salt together 3 times. Add alternately with buttermilk.","Last, mix vinegar with soda and fold into batter. Do not beat.","Pour into greased and floured pans; bake in 350° oven 35 minutes."]},{"heading":"Icing","items":["Mix flour, salt and milk and cook until thick, cool. This is very important.","Beat sugar and shortening at high speed until fluffy.","Add to cooled mixture, beat again until light and fluffy. Add vanilla.","May be garnished with coconut, nuts or fruit."]}],"notes":[],"images":[{"file":"0042-b.jpg","label":"Front"},{"file":"0042-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"roast-with-pinto-beans-and-green-chilies","title":"Roast with Pinto Beans and Green Chilies","from":null,"card":"0095","tags":["main dish","beef","roast","pot roast","pinto beans","beans","green chilies","tomatoes","tomato sauce","onion","slow cooking"],"ingredients":[{"heading":null,"items":["Roast","2 c. pinto beans","1 can green chilies","1 can tomatoes","1 can tomato sauce","1 onion, chopped"]}],"directions":[{"heading":null,"items":["Cover with water. Season to taste.","Cook at 250° for 12 hrs."]}],"notes":[],"images":[{"file":"0095-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"rr-chili","title":"RR Chili","from":null,"card":"loose-09","tags":["chili","main dish","beef","steak","ground beef","tomato"],"ingredients":[{"heading":null,"items":["Steak, cut small (1/4\" or less)","85% ground chuck","Water","Spices","Red tomato juice"]}],"directions":[{"heading":null,"items":["Cook the steak; pour the oil off and replace with water.","Add spices and cook [45?] minutes.","Add red tomato juice for color.","Add more spices as desired."]}],"notes":["Written at the bottom of the card: \"[ICS?] Trophy.\" ICS likely stands for the International Chili Society."],"images":[{"file":"loose-09.jpg","label":"Scan"}],"sameCard":[]},{"slug":"salmon-patties","title":"Salmon Patties","from":null,"card":"0090","tags":["main dish","fish","salmon","eggs","crackers","saltines","lemon","onion","garlic","fried"],"ingredients":[{"heading":null,"items":["1 can salmon (flaked)","6 eggs (beaten)","1/4 box saltine crackers (crushed)","Lemon juice","Garlic salt","Salt","Black pepper","Chopped onions"]}],"directions":[{"heading":null,"items":["Mix salmon, eggs and crackers in pan.","Add lemon juice, garlic salt, salt, black pepper and chopped onions to flavor taste.","Fry into hot veg. oil until brown both sides."]}],"notes":[],"images":[{"file":"0090-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"salsa","title":"Salsa","from":null,"card":"0080","tags":["salsa","sauce","dip","mexican","tomatoes","onion","garlic","jalapeños","hot","blender"],"ingredients":[{"heading":null,"items":["1 can tomatoes","1/2 onion, cut up","3 pods of garlic, cut up","Jalapeños (optional) - 1 to start"]}],"directions":[{"heading":null,"items":["Mix ingredients in blender. Blend to liquid - completely (no pieces)."]}],"notes":["Also on the card, about pequin chili with seeds: \"Will be Very Hot!\"","The Nachos recipe is on the back of this card."],"images":[{"file":"0080-b.jpg","label":"Front"},{"file":"0080-a.jpg","label":"Back"}],"sameCard":["nachos"]},{"slug":"shells-and-cheese-florentine","title":"Shells and Cheese Florentine","from":null,"card":"0147","tags":["side dish","main dish","pasta","macaroni and cheese","shells","cheese","velveeta","spinach","mushrooms","onion","margarine","kraft"],"ingredients":[{"heading":null,"items":["1 package (12 ounces) Velveeta Shells & Cheese","3 cups shredded spinach","1 cup mushroom slices","1/2 cup chopped onion","2 tablespoons Parkay Margarine","Fresh spinach"]}],"directions":[{"heading":null,"items":["Prepare Shells and Cheese as directed on package except adding spinach to blanch during last 30 seconds of boiling Shell Macaroni. Continue as directed on package.","Saute mushrooms and onion in margarine. Add to Shells and Cheese and spinach, mix well.","Serve over bed of spinach leaves."]}],"notes":["From a Kraft Velveeta recipe leaflet.","Makes 6 servings. Prep time: 10 minutes. Cooking time: 15 minutes."],"images":[{"file":"0147-b.jpg","label":"Front"},{"file":"0147-a.jpg","label":"Back"}],"sameCard":["cheesy-chicken-enchiladas","mexican-chili-burgers","chicken-fajita-pizzas","tex-mex-fondue"]},{"slug":"silky-cocoa-creme","title":"Silky Cocoa Creme","from":null,"card":"0148","tags":["dessert","mousse","molded dessert","chocolate","cocoa","hershey's","gelatin","ricotta","whipped topping","strawberries","light","low-fat"],"ingredients":[{"heading":null,"items":["1 envelope unflavored gelatin","1/4 cup cold water","1/2 cup sugar","1/3 cup Hershey's Cocoa","1/2 cup part-skim ricotta cheese","3/4 cup skim milk","1 teaspoon vanilla extract","1/2 cup frozen light non-dairy whipped topping, thawed","Fresh strawberries"]}],"directions":[{"heading":null,"items":["In small bowl, sprinkle gelatin over water; allow to stand 2 minutes to soften.","In medium saucepan, stir together sugar and cocoa; stir in milk. Cook over medium heat, stirring constantly until mixture is very hot.","Add gelatin mixture, stirring until gelatin is dissolved; pour into medium bowl. Refrigerate until mixture is chilled (do not allow to gel).","In blender container or food processor bowl, beat ricotta cheese and vanilla until smooth; stir into whipped topping.","Gradually fold into cocoa mixture; pour into 2-cup mold. Refrigerate until set.","Unmold; serve with strawberries."]}],"notes":["From a Hershey's Cocoa label leaflet, \"The Lean Way to Make it Chocolate!\"","Makes 8 servings. Per serving: 110 calories, 5 mg cholesterol, 3 g fat."],"images":[{"file":"0148-b.jpg","label":"Front"},{"file":"0148-a.jpg","label":"Back"}],"sameCard":["fruit-filled-chocolate-dreams","chocolate-cupcakes","chocolate-ricotta-cheesecake","hersheys-light-chocolate-cake","creamy-chocolate-and-peach-layered-pudding"]},{"slug":"single-pie-crust","title":"Single Pie Crust","from":null,"card":"0082","tags":["pie crust","pastry","pie","flour","shortening","crisco","baking"],"ingredients":[{"heading":"2 Pie Crust","items":["1 1/2 cups flour","2/3 cups Crisco","1/2 tsp salt","1/3 cup ice water"]},{"heading":"6 Pie Crusts","items":["4 1/2 cups flour","2 cups shortening","1 1/2 tsp salt","1 cup ice water"]}],"directions":[{"heading":null,"items":["Bake @ 425 to lt. brown."]}],"notes":["\"Lt. brown\" means light brown."],"images":[{"file":"0082-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"skor","title":"Skor","from":null,"card":"0131","tags":["candy","bars","cookies","dessert","toffee","butter","brown sugar","chocolate","hershey's","christmas candy"],"ingredients":[{"heading":null,"items":["1 c butter","1 c brown sugar","1 egg white","1 c flour","6 Hershey's chocolate bars"]}],"directions":[{"heading":null,"items":["Cream butter, brown sugar and egg white. Add flour.","Put into a greased big flat baking pan (15 x 10). Cook 15-20 minutes at 350°.","When it comes out hot, lay 6 Hershey's chocolate bars on top and spread them over it as they soften.","Let cool, then break into pieces."]}],"notes":["Another version is on card 0146."],"images":[{"file":"0131-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"sopaipillas-0140","title":"Sopaipillas","from":null,"card":"0140","tags":["bread","fried bread","sopaipillas","mexican","new mexican","flour","lard","shortening","honey","cinnamon","deep fried"],"ingredients":[{"heading":null,"items":["2 cups flour","1 tsp baking powder","1 level tsp salt","1 tbs lard or shortening","Warm water (app. 12 tbs)"]}],"directions":[{"heading":null,"items":["Mix flour, baking powder, salt, sugar until well blended.","Add enough warm water to make a medium soft dough, like pie crust.","Place dough in covered bowl and allow to stand at room temperature for thirty minutes.","Then roll dough out on floured board evenly at 1/8 inch thickness. Cut into 3 inch squares and fry in deep hot fat until fluffy brown.","Remove from fat and drain on paper towel. Serve hot."]}],"notes":["Makes about two dozen. Serve with honey, or sprinkle with sugar and cinnamon.","Another version is on card 0141."],"images":[{"file":"0140-b.jpg","label":"Front"},{"file":"0140-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"sopaipillas-0141","title":"Sopaipillas","from":null,"card":"0141","tags":["bread","fried bread","sopaipillas","mexican","new mexican","flour","shortening","deep fried"],"ingredients":[{"heading":null,"items":["1 3/4 c sifted flour","2 tsp baking powder","1 tsp salt","2 tbsp shortening","Oil for deep frying"]}],"directions":[{"heading":null,"items":["No directions on the card."]}],"notes":["Another version is on card 0140."],"images":[{"file":"0141-a.jpg","label":"Front"},{"file":"0141-b.jpg","label":"Back"}],"sameCard":["flour-tortillas"]},{"slug":"sour-cream-chocolate-torte","title":"Sour Cream Chocolate Torte","from":null,"card":"0049","tags":["cake","torte","dessert","chocolate","sour cream","brown sugar","whipped cream","layer cake","baking"],"ingredients":[{"heading":null,"items":["1 cup boiling water","3 squares (1 oz. each) unsweetened chocolate","2 cups sifted flour","2 tsp. baking soda","1 tsp. salt","1 cup dairy sour cream","1 tsp. vanilla extract","2 eggs","1 cup sugar","1 cup firmly packed light brown sugar","1 cup (1/2 pt.) heavy cream, whipped","3 Tbsp. confectioners sugar","Confectioners sugar"]}],"directions":[{"heading":null,"items":["Pour water over chocolate in saucepan. Heat to boiling and cook gently until mixture starts to thicken, stirring occasionally. Remove from heat and cool.","Sift together flour, baking soda and salt. Combine sour cream and vanilla.","Beat together eggs, sugar and brown sugar until thick and creamy.","Add flour mixture to egg mixture alternately with sour cream mixture, beginning and ending with flour. Blend in chocolate.","Turn into 2 greased wax paper lined 8-inch round cake pans. Bake in preheated 350° gas oven, 30 to 35 minutes, or until done.","Cool in pans 10 minutes before removing. Cool completely and split each layer horizontally in half.","Beat cream and 3 Tbsp. confectioners sugar together until stiff. Spread between cake layers.","Place paper doily over top of cake and sprinkle with confectioners sugar. Remove doily carefully to leave design. Serve immediately or refrigerate until ready to serve."]}],"notes":[],"images":[{"file":"0049-b.jpg","label":"Front"},{"file":"0049-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"sourdough-biscuits","title":"Sourdough Biscuits","from":null,"card":"0073","tags":["biscuits","bread","sourdough","sourdough starter","milk","flour","make-ahead","baking"],"ingredients":[{"heading":null,"items":["1/2 cup sourdough Starter","1 cup milk","2 1/2 cups unsifted flour","3/4 tsp salt","1 tablespoon sugar","1 tsp baking pwd","1/2 tsp soda - scant","Salad oil, butter, or grease"]}],"directions":[{"heading":null,"items":["Mix starter, milk & 1 cup flour. Prepare night before, cover & keep at room temp.","Turn this onto 1 cup flour on bread board.","Combine salt, sugar, baking pwd & soda with remaining 1/2 cup flour & sift over top.","Mix dry ingredients into dough, kneading lightly.","Roll out [1/2?] in thickness. Cut out, dip in warm grease.","Let rise for 1/2 hr. Bake in oven 375°. 14 biscuits."]}],"notes":["The Sourdough Pancakes recipe is on the back of this card."],"images":[{"file":"0073-a.jpg","label":"Front"},{"file":"0073-b.jpg","label":"Back"}],"sameCard":["sourdough-pancakes"]},{"slug":"sourdough-bread","title":"Sourdough Bread","from":null,"card":"0112","tags":["bread","yeast bread","sourdough","starter","flour","yeast","sugar","egg","oil","milk","baking"],"ingredients":[{"heading":null,"items":["1 pkg. dry yeast","1/2 c. warm water","1/3 c. sugar","1 c. starter","1 egg or 1/3 c. oil","1 1/2 tsp. salt","1 c. warm water","5 or 6 c. flour"]},{"heading":"Starter feeding","items":["1 c. milk","1 c. flour","1/3 c. sugar"]}],"directions":[{"heading":null,"items":["Dissolve yeast in 1/2 c. warm water and 1/3 c. sugar. Let sit 15 min.","Add 1 c. starter. Let set 15 min.","Add 1 egg or 1/3 c. oil; 1 1/2 tsp. salt; 1 c. warm water; 5 or 6 c. flour. Knead until elastic.","Let rise 2 hrs. Punch down and shape into loaves.","Let rise 30 min. Bake at 350° 30 to 40 min. Makes 2 loaves."]},{"heading":"Starter feeding","items":["Use once a week or feed — wait 24 hrs."]}],"notes":["Written on a printed recipe card with a pink chef illustration."],"images":[{"file":"0112-b.jpg","label":"Front"},{"file":"0112-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"sourdough-pancakes","title":"Sourdough Pancakes","from":null,"card":"0073","tags":["pancakes","breakfast","sourdough","sourdough starter","eggs","griddle","make-ahead"],"ingredients":[{"heading":null,"items":["1/2 cup sourdough starter","2 cups flour","2 cups lukewarm water","2 level tablespoons sugar","1 tsp salt","3 tablespoons melted shortening","2 eggs","1 tsp Baking soda"]}],"directions":[{"heading":null,"items":["1/2 cup starter: add 2 cups flour, 2 cups lukewarm water. Beat until smooth & let stand in warm place overnight.","To dough: add sugar, salt, melted shortening. Beat in eggs.","Dissolve soda in tablespoon water, fold in gently. Do not stir after soda has been added.","Grease griddle & fry."]}],"notes":["Noted in the margin: \"First Edition Arizona Cook book\" (Booksmith, Tucson), likely where the recipe came from.","Written on the back of the Sourdough Biscuits card."],"images":[{"file":"0073-a.jpg","label":"Front"},{"file":"0073-b.jpg","label":"Back"}],"sameCard":["sourdough-biscuits"]},{"slug":"spaghetti-sauce-for-freezer","title":"Spaghetti Sauce for Freezer","from":null,"card":"0009","tags":["sauce","spaghetti sauce","main dish","pasta","ground beef","tomatoes","tomato paste","mushroom","make-ahead","freezer"],"ingredients":[{"heading":null,"items":["4 - 5 lbs. ground beef","2 large onions","2 cloves garlic","2 cups chopped celery","4 cans whole tomatoes","2 Tbsp. paprika","2 Tbsp. chili powder","4 cans tomato paste","2 cans mushroom sauce","Salt and pepper","1/2 cup parsley","4 bay leaves","2 Tbsp. sugar","4 cups hot water"]}],"directions":[{"heading":null,"items":["Simmer 2 - 3 hours."]}],"notes":["Makes enough for 4 meals."],"images":[{"file":"0009-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"spanish-rice-0038","title":"Spanish Rice","from":null,"card":"0038","tags":["main dish","rice","spanish rice","hamburger","ground beef","beef","tomatoes","tomato sauce","green pepper","onion","curry powder","bay leaves"],"ingredients":[{"heading":null,"items":["1 onion","1 whole green pepper","1 lb. hamburger, browned","1 can whole tomatoes","1 can tomato sauce","1 can each water","Salt and pepper","3 bay leaves","Garlic powder","1 Tbsp. curry powder","2 cups rice"]}],"directions":[{"heading":null,"items":["Simmer 1 1/2 hours.","Cook 2 cups rice and combine."]}],"notes":[],"images":[{"file":"0038-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"spanish-rice","title":"Spanish Rice","from":null,"card":"0010","tags":["side dish","rice","tomatoes","green pepper","onion","celery","chili powder","worcestershire sauce"],"ingredients":[{"heading":null,"items":["2 cups cooked rice","1 cup tomatoes","1 cup water","1/2 cup chopped onions","1/3 cup chopped green peppers","1/2 cup chopped celery","3 tbs oil","1 tsp salt","1 tsp sugar","1/2 tsp chili powder","1/2 tsp Worcestershire sauce","1 bay leaf"]}],"directions":[{"heading":null,"items":["Sauté onions, green pepper and celery in oil.","Add other ingredients and simmer until thick."]}],"notes":["Serves 6."],"images":[{"file":"0010-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"spicy-apple-cobbler","title":"Spicy Apple Cobbler","from":null,"card":"0008","tags":["cobbler","dessert","apple","cinnamon","nutmeg","brown sugar","imperial sugar","baking"],"ingredients":[{"heading":null,"items":["4 or 5 medium apples","1/4 cup Imperial Brown Sugar","2 Tbsp. butter","1 tsp. cinnamon","1 tsp. nutmeg","1 cup Imperial Pure Cane Granulated Sugar","1 cup sifted flour","1/2 tsp. salt","1 tsp. baking powder","1/2 cup milk","2 Tbsp. melted butter"]}],"directions":[{"heading":null,"items":["Peel and slice apples in 8\" x 8\" x 2\" square cake pan.","Sprinkle with Imperial Brown Sugar; dot with butter, then sprinkle with cinnamon and nutmeg.","Combine Imperial Pure Cane Granulated Sugar, flour, salt, baking powder, milk and melted butter into batter; pour over apple mixture.","Bake at 350° F. about 45 minutes.","Serve either hot or cold with whipped cream."]}],"notes":["Makes 6 servings."],"images":[{"file":"0008-b.jpg","label":"Front"},{"file":"0008-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"stuffed-peppers","title":"Stuffed Peppers","from":null,"card":"0037","tags":["main dish","stuffed peppers","green peppers","ground beef","beef","rice","tomatoes","cheese","onion","worcestershire","baking"],"ingredients":[{"heading":null,"items":["6 medium green peppers","1 pound ground beef","1/3 cup chopped onion","1 T. fat","2 cups stewed tomatoes or 1 (1 lb.) can","3/4 c. packaged precooked rice","2 T. Worcestershire sauce","Salt & pepper","1 c. shredded sharp process American cheese"]}],"directions":[{"heading":null,"items":["Cut off tops of green peppers; remove seeds and membrane.","Precook green-pepper cups in boiling salted water about 5 minutes; drain. Sprinkle inside with salt. (For crisp peppers, omit precooking.)","Brown meat and onion in hot fat; add tomatoes, rice, Worcestershire, and salt and pepper to taste.","Cover and simmer till rice is almost tender, about 5 minutes. Add cheese.","Stuff peppers; stand upright in 10 x 6 x 1 1/2 inch baking dish.","Bake uncovered at 350° for 25 minutes or till hot. Sprinkle with more cheese."]}],"notes":["Serves 6."],"images":[{"file":"0037-b.jpg","label":"Front"},{"file":"0037-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"taco-soup","title":"Taco Soup","from":null,"card":"0117","tags":["soup","main dish","ground beef","beef","pinto beans","beans","tomatoes","corn","rotel","green chilies","ranch dressing mix","taco seasoning"],"ingredients":[{"heading":null,"items":["1 lb. ground beef (1 1/2 lb.), browned","2 cans pinto beans, undrained","1 can diced tomatoes, undrained","1 can corn, undrained","1 can Rotel or green chilies","1 pkg. dry Hidden Valley Ranch dressing","1 pkg. taco seasoning dry mix"]}],"directions":[{"heading":null,"items":["After meat is browned, add canned goods & dry pkg. Heat thoroughly."]}],"notes":[],"images":[{"file":"0117-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"tea-cake","title":"Tea Cake","from":null,"card":"0015","tags":["cookies","tea cakes","dessert","crisco","vanilla","rolled cookies","baking"],"ingredients":[{"heading":null,"items":["1 cup Crisco","2 cups sugar","1 cup milk","4 eggs","3 cups flour","2 tsp. vanilla","1 tsp. baking powder"]}],"directions":[{"heading":null,"items":["Roll and bake at 350°."]}],"notes":["Amounts for a quadruple batch are written in the margin: 4 Crisco, 8 sugar, 4 milk, 16 eggs, 12 flour, 8 vanilla, 4 baking powder."],"images":[{"file":"0015-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"tea-cakes","title":"Tea Cakes","from":null,"card":"0056","tags":["cookies","tea cakes","dessert","sugar cookies","rolled cookies","butter","shortening","vanilla","baking"],"ingredients":[{"heading":null,"items":["3 1/2 cups flour","1 1/4 cups sugar","5 tsp. baking powder","1/2 tsp. salt","3 eggs","2 tsp. vanilla","1 cup shortening","1/2 cup butter","Sugar, for sprinkling"]}],"directions":[{"heading":null,"items":["Sift all dry ingredients into large bowl.","Cut in shortening, add unbeaten eggs and vanilla. Stir in thoroughly.","Roll thin on floured board, cut and shape, sprinkle with sugar and bake in oven at 450°."]}],"notes":["Amounts for a double batch are written in the margin: flour 7, sugar 2 1/2, baking powder 10, salt 1, eggs 6, vanilla 4, shortening 2, butter 1.","Amounts for a triple batch are also written in the margin: flour 10 1/2, sugar 3 3/4, baking powder 15, salt 1 1/2, eggs 9, vanilla 6, shortening 3, butter 1 1/2."],"images":[{"file":"0056-a.jpg","label":"Front"},{"file":"0056-b.jpg","label":"Back"}],"sameCard":[]},{"slug":"texas-barbecue-sauce","title":"Texas Barbecue Sauce","from":null,"card":"0061","tags":["sauce","barbecue","barbecue sauce","blue bonnet","margarine","garlic","onion","lemon","worcestershire","chili sauce","tabasco","dry mustard"],"ingredients":[{"heading":null,"items":["1/2 cup Blue Bonnet Margarine","1 clove garlic, mashed","1/4 cup grated onion","1/4 cup lemon juice","1/4 cup Worcestershire sauce","1 Tbsp. dry mustard","1 cup chili sauce","1/4 tsp. Tabasco"]}],"directions":[{"heading":null,"items":["Melt Blue Bonnet Margarine in saucepan. Add garlic and onion and stir over medium heat for 2 minutes.","Add remaining ingredients, stirring until sauce bubbles and thickens slightly.","Reduce heat, cover, and simmer gently about 20 minutes."]}],"notes":["From a Blue Bonnet Margarine recipe.","Makes 1 pint."],"images":[{"file":"0061-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"tex-mex-fondue","title":"Tex-Mex Fondue","from":null,"card":"0147","tags":["appetizer","dip","fondue","cheese","velveeta","jalapeno","tequila","lime","cilantro","mexican","microwave","kraft"],"ingredients":[{"heading":null,"items":["1/4 cup tequila or chicken broth","1 garlic clove, minced","1 lb. Velveeta Mexican Process Cheese Spread with Jalapeno Pepper, cubed","2 tablespoons lime juice","2 tablespoons chopped cilantro","For dipping: cooked chicken chunks, jicama chunks, red, green or yellow pepper chunks, tortilla chips"]}],"directions":[{"heading":null,"items":["Mix together tequila and garlic in 1 1/2 quart bowl. Microwave on HIGH 2-3 minutes or until hot.","Stir in process cheese spread and lime juice.","Microwave 3 to 4 minutes or until process cheese spread is melted, stirring every 2 minutes.","Stir in cilantro.","Keep fondue hot while serving. Dip cooked chicken chunks, jicama chunks, red, green or yellow pepper chunks and tortilla chips into fondue."]},{"heading":"Conventional","items":["Heat tequila and garlic in medium saucepan or fondue pot. Bring to boil. Reduce heat; simmer 1 minute.","Add process cheese spread and lime juice; stir until process cheese spread is melted.","Stir in cilantro. Serve as directed."]}],"notes":["From a Kraft Velveeta recipe leaflet.","Makes 4 servings. Prep time: 5 minutes. Microwave cooking time: 7 minutes. Conventional cooking time: 5 minutes."],"images":[{"file":"0147-b.jpg","label":"Front"},{"file":"0147-a.jpg","label":"Back"}],"sameCard":["cheesy-chicken-enchiladas","shells-and-cheese-florentine","mexican-chili-burgers","chicken-fajita-pizzas"]},{"slug":"tortilla-rolls","title":"Tortilla Rolls","from":null,"card":"0111","tags":["appetizer","snack","pinwheels","tortillas","cream cheese","green chilies","pimentos","garlic salt","make-ahead","party"],"ingredients":[{"heading":null,"items":["Large flour tortillas (6)","Soft cream cheese (large tub) or 1 1/2 stick, softened","Small can green chilies","Small jar pimentos","Garlic salt & Nature's Seasons to taste","Dash of paprika"]}],"directions":[{"heading":null,"items":["Mix together and spread on tortilla; roll.","Wrap in wax paper. Refrig. overnight; cut."]}],"notes":["Nature's Seasons is a Morton seasoning blend."],"images":[{"file":"0111-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"tortillas","title":"Tortillas","from":null,"card":"0093","tags":["tortillas","bread","flour","mexican","shortening","griddle"],"ingredients":[{"heading":null,"items":["2 cups flour","2 tsp. baking powder","3/4 tsp. salt","3 tablespoons shortening - oil","1 1/2 cups cold water"]}],"directions":[{"heading":null,"items":["In a bowl combine ingredients.","Cover w/ a damp towel for 30 min.","Knead 5 min. on lightly floured surface.","Shape dough into 5 balls of equal size and roll out to desired round size.","Put on heated griddle to cook."]}],"notes":[],"images":[{"file":"0093-b.jpg","label":"Front"},{"file":"0093-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"tortillas-de-maiz","title":"Tortillas de Maiz","from":null,"card":"0074","tags":["tortillas","bread","mexican","southwestern","corn","masa harina","blue corn","electric skillet"],"ingredients":[{"heading":null,"items":["2 cups blue or yellow corn masa harina","1 teaspoon salt","1 2/3 cups boiling water"]}],"directions":[{"heading":null,"items":["Combine corn masa harina and salt in mixing bowl.","Add boiling water and stir until dough resembles thick cooked cereal. Set dough aside for 30 minutes.","Wet hands lightly and form dough into balls the size of hen's eggs.","Place each ball of dough between two very lightly moistened pieces of waxed paper and flatten to about 1/8 inch using a tortilla press, rolling pin, or pressure from hand.","Remove tortilla from waxed paper and bake on lightly greased pre-heated electric skillet, turning to very lightly brown tortilla on both sides."]}],"notes":["From a Clovis, New Mexico newspaper clipping, made in an electric skillet.","Makes 12–14 tortillas. Heat the skillet to 420°F.","Tip from the clipping: one-half cup all-purpose flour may be added to make the dough easier to handle (add slightly more water)."],"images":[{"file":"0074-b.jpg","label":"Clipping"},{"file":"0074-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"tuna-salad","title":"Tuna Salad","from":null,"card":"loose-01","tags":["salad","tuna","fish","eggs","mayonnaise","pickles","onion","celery","sandwich filling"],"ingredients":[{"heading":null,"items":["2 boiled eggs","Mayonnaise","Pickles","Onion","Celery"]}],"directions":[{"heading":null,"items":["(No directions on the card.)"]}],"notes":[],"images":[{"file":"loose-01.jpg","label":"Scan"}],"sameCard":[]},{"slug":"twin-cookie-sandwiches","title":"Twin-Cookie Sandwiches","from":null,"card":"0004","tags":["cookies","sandwich cookies","dessert","cut-out cookies","hearts","lemon","frosting","domino sugar","baking"],"ingredients":[{"heading":null,"items":["1 cup Domino Extra Fine Granulated Sugar","1/2 tsp. salt","3/4 cup soft butter or margarine","1 egg","1 tsp. grated lemon rind","1 tsp. vanilla extract","3 cups sifted all-purpose flour","1 tsp. double-acting baking powder"]},{"heading":"Filling","items":["1 egg white","2 to 2 1/2 cups Domino Confectioners Pow. Sugar","1 Tbsp. melted butter or margarine","1/8 tsp. salt","1/2 tsp. vanilla extract","Red food coloring"]}],"directions":[{"heading":null,"items":["Cream granulated sugar, salt and butter or margarine well. Blend egg, lemon rind and extract into mixture.","Sift flour and baking powder together; stir into cream ingredients.","Divide dough in thirds. Form each into a ball. Pat down on floured board and roll about 1/8\" thick.","Cut 2 3/4\" hearts with floured cutter. Cut center from half of cookies with 1 1/2\" heart cutter.","Place all hearts (plain ones, cut-out tops and tiny hearts) on ungreased cookie sheets. Bake in moderate oven (350°F.) 7 - 8 minutes."]},{"heading":"Filling","items":["Beat egg white and confectioners sugar. Add butter or margarine, salt and extract. Tint pink with food coloring.","Make large sandwiches by spreading plain hearts and pressing cut-out tops on. Make tiny sandwiches by spreading filling between small hearts."]}],"notes":["Makes 2 1/2 dozen large sandwiches and 2 1/2 dozen small sandwiches."],"images":[{"file":"0004-b.jpg","label":"Front"},{"file":"0004-a.jpg","label":"Back"}],"sameCard":[]},{"slug":"vicki-maize-cornbread","title":"Vicki Maize Cornbread","from":"Vicki Maize","card":"0092","tags":["cornbread","bread","main dish","casserole","corn","cream corn","hamburger","ground beef","green chili","onion","cheese","martha white","baking"],"ingredients":[{"heading":null,"items":["Martha White mix (cornbread mix)","1 egg","Milk"]},{"heading":"Filling","items":["1 lb. hamburger meat (brown)","1 can cream corn","1 chopped onion","1 can green chili, mild","1 pk. Mexican shredded cheese"]}],"directions":[{"heading":null,"items":["Brown the hamburger meat. Mix together with the cream corn, onion, green chili and cheese.","Mix cornbread mix + 1 egg + milk.","Pour 1/2 cornbread mix into greased baking pan, then add other mix in the center. Cover with the balance of cornbread mix.","Cook 40 - [60?] minutes @ 350°."]}],"notes":["Mitchel Corn Bread, a different recipe, is on the back of this card."],"images":[{"file":"0092-b.jpg","label":"Front"},{"file":"0092-a.jpg","label":"Back"}],"sameCard":["mitchel-corn-bread"]},{"slug":"vickis-pancakes","title":"Vicki's Pancakes","from":"[Vicki Maize?]","card":"0091","tags":["pancakes","breakfast","bread","flour","eggs","milk","bacon grease"],"ingredients":[{"heading":null,"items":["1 1/4 cup flour","2 tbs. sugar","2 tsp. baking powder","1/2 tsp. salt","1 egg (beaten)","1 tbs. Wesson oil","1 cup milk"]}],"directions":[{"heading":null,"items":["Leave slightly lumpy.","Cook with bacon grease."]}],"notes":[],"images":[{"file":"0091-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"vikes-witches-brew","title":"Viki's Witches Brew","from":"Viki Love","card":"0103","tags":["drink","beverage","drink mix","spiced tea","tea","instant tea","tang","orange","lemon peel","cinnamon","cloves"],"ingredients":[{"heading":null,"items":["2 cups Tang","1 cup sugar","1/2 cup instant tea","1 tsp. dry lemon peel","1 tsp. cinnamon","1/2 tsp. cloves"]}],"directions":[{"heading":null,"items":["(No directions on the card.)"]}],"notes":[],"images":[{"file":"0103-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"watermelon-rind-preserves","title":"Watermelon Rind Preserves","from":null,"card":"0053","tags":["preserves","canning","watermelon","watermelon rind","sugar","syrup","lime water"],"ingredients":[{"heading":null,"items":["4 lbs. prepared watermelon rinds, cut in inch cubes","[Lime?] water to cover"]},{"heading":"Syrup","items":["7 cups sugar","2–3 cups syrup (white)","6 cups water"]}],"directions":[{"heading":null,"items":["Cut 4 lbs. prepared watermelon rinds in inch cubes. [Lime?] water to cover."]}],"notes":[],"images":[{"file":"0053-a.jpg","label":"Front"}],"sameCard":[]},{"slug":"white-fruit-cake","title":"White Fruit Cake","from":null,"card":"0040","tags":["cake","fruitcake","dessert","christmas","holiday","pecans","cherries","pineapple","coconut","lemon extract","butter","baking"],"ingredients":[{"heading":null,"items":["2 cups of sugar","1 lb. of butter","8 eggs, beaten","4 cups of flour","1 tsp. of baking powder","1 lb. of chopped pecans","1 lb. chopped cherries","1 lb. of chopped pineapple","1 small can coconut","1 small lemon extract"]}],"directions":[{"heading":null,"items":["Bake in angel food cake pan, 250°, 3 hrs.","Or [half?] [an?] oblong pan, 1 1/2 hr @ 250°.","Put water in pan in bottom of oven."]}],"notes":[],"images":[{"file":"0040-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"wild-west-chili","title":"[Wild?] West Chili","from":null,"card":"loose-10","tags":["chili","soup","main dish","ground beef","beef","venison","bacon","tomatoes","chili beans","beans","celery","carrots","green pepper"],"ingredients":[{"heading":null,"items":["2 bacon strips, diced","1 pound ground beef or venison","2 teaspoons chili powder","1 1/2 teaspoons salt","1/4 teaspoon garlic salt","1/4 teaspoon dried oregano","1/8 teaspoon cayenne pepper","3 to 5 drops hot pepper sauce","1 can (14 1/2 ounces) diced tomatoes, undrained","1 cup each finely chopped celery, onion and carrots","1/2 cup finely chopped green pepper","1 can (16 ounces) chili beans, undrained"]}],"directions":[{"heading":null,"items":["In a large saucepan over medium heat, brown bacon and the beef or venison; drain.","Add the seasonings; cook and stir for 5 minutes.","Stir in tomatoes, celery, onion, carrots and green pepper; bring to a boil.","Reduce heat; cover and simmer for 40 minutes.","Stir in beans; cook 30 minutes longer."]}],"notes":["From a magazine clipping.","Makes 6 servings."],"images":[{"file":"loose-10.jpg","label":"Scan"}],"sameCard":[]},{"slug":"yum-yum","title":"Yum Yum","from":null,"card":"0138","tags":["salad","dessert","gelatin","jello","pineapple","cheese","pecans","nuts","cool whip","whipped topping"],"ingredients":[{"heading":null,"items":["1/2 cup water","1 can pineapple","1/2 cup sugar","1 cup cheese","1/2 cup pecans","1 ctn. Cool Whip","1 small pkg. Jello"]}],"directions":[{"heading":null,"items":["No directions on the card."]}],"notes":["Another version is on card 0089."],"images":[{"file":"0138-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"yum-yum-salad","title":"Yum Yum Salad","from":"Della Mitchell","card":"0089","tags":["salad","dessert","gelatin","jello","pineapple","cheese","cheddar","pecans","nuts","whipping cream","make-ahead"],"ingredients":[{"heading":null,"items":["2 c. crushed pineapple","1/2 c. sugar","1 small box Jello","1/2 c. boiling water","1 c. grated cheese (Cheddar)","1/2 c. chopped pecans","1 ctn. whipping cream, beaten stiff"]}],"directions":[{"heading":null,"items":["Mix pineapple and sugar. Heat until sugar dissolves. Remove from heat.","Mix Jello and boiling water. Mix this with pineapple mixture and let set until jelled (not hard).","Add cheese, pecans and whipped cream. Mix all together and put in mold. Let set 12-24 hours."]}],"notes":["From Della Mitchell, Clovis, N.M.","Another version is on card 0138."],"images":[{"file":"0089-b.jpg","label":"Front"}],"sameCard":[]},{"slug":"zucchini-bread-loose-02","title":"Zucchini Bread","from":"[Robbie?] Peters","card":"loose-02","tags":["bread","quick bread","zucchini","cinnamon","nutmeg","ginger","brown sugar","eggs","oil","baking"],"ingredients":[{"heading":null,"items":["1 tsp. baking soda","1 tsp. baking powder","2 1/2 cups flour","1 cup brown sugar","1 cup white sugar","1 cup oil","4 eggs","1 tblspn. cinnamon","1 tsp. nutmeg","1 tsp. vanilla","1/2 tsp. ginger","2 cups zucchini"]}],"directions":[{"heading":null,"items":["Mix all dry and all wet, then mix together.","Bake at 350° for 1:15."]}],"notes":["From [Robbie?] Peters.","\"1:15\" means 1 hour 15 minutes."],"images":[{"file":"loose-02.jpg","label":"Scan"}],"sameCard":[]},{"slug":"zucchini-bread","title":"Zucchini Bread","from":null,"card":"0012","tags":["bread","quick bread","bundt cake","zucchini","squash","cinnamon","nuts","crisco","baking"],"ingredients":[{"heading":null,"items":["3 eggs","1 cup Crisco oil","2 C. sugar","2 C. zucchini squash, grated","2 1/2 flour","1 tsp soda","1 tsp salt","1/4 teas. baking powder","1 heaping tablespoon cinnamon","1 cup nuts","1 tsp vanilla"]}],"directions":[{"heading":null,"items":["350° 1 hr."]}],"notes":["Makes two loaves or 1 Bundt cake."],"images":[{"file":"0012-b.jpg","label":"Front"},{"file":"0012-a.jpg","label":"Back"}],"sameCard":[]}];
